	/** Submits the value with a native form through a hidden input. */
	name?: string;
	/** Accessible name for the input; the buttons read "Increase {label}". */
	label?: string;
	className?: string;
}

function decimalsOf(value: number) {
	if (!Number.isFinite(value)) return 0;
	const text = String(value);
	if (text.includes("e-")) return Number(text.split("e-")[1]);
	return text.split(".")[1]?.length ?? 0;
}

function clamp(value: number, min: number, max: number) {
	return Math.min(Math.max(value, min), max);
}

type Separators = { group: string; decimal: string };

function getSeparators(locale?: string): Separators {
	const parts = new Intl.NumberFormat(locale).formatToParts(12345.6);
	return {
		group: parts.find((part) => part.type === "group")?.value ?? ",",
		decimal: parts.find((part) => part.type === "decimal")?.value ?? ".",
	};
}

/** Reduces locale text to digits, `-`, and a `.` decimal point. */
function normalizeNumber(text: string, { group, decimal }: Separators) {
	return text
		.replace(/[\s  ]/g, "")
		.split(group)
		.join("")
		.split(decimal)
		.join(".")
		.replace(/[−‒-—]/g, "-")
		.replace(/[^\d.-]/g, "");
}

function parseNumber(text: string, separators: Separators, percent: boolean) {
	const clean = normalizeNumber(text, separators);
	const negative = clean.startsWith("-");
	const [whole = "", ...fraction] = clean.replace(/-/g, "").split(".");
	const digits = fraction.length ? `${whole}.${fraction.join("")}` : whole;
	if (!/\d/.test(digits)) return Number.NaN;
	const parsed = Number(digits) * (negative ? -1 : 1);
	// Percent values are fractions: typing "15" in a percent field means 0.15.
	return percent ? parsed / 100 : parsed;
}

export function NumberStepper({
	value: valueProp,
	defaultValue = 1,
	onValueChange,
	onValueCommit,
	min = 0,
	max = Number.POSITIVE_INFINITY,
	step = 1,
	largeStep = 10,
	accelerate = true,
	format,
	locale,
	wheel = false,
	size = "md",
	variant = "outline",
	orientation = "horizontal",
	sound = true,
	haptics = true,
	disabled = false,
	readOnly = false,
	name,
	label = "Value",
	className,
}: NumberStepperProps) {
	const horizontal = orientation === "horizontal";
	const inactive = disabled || readOnly;
	const percent = format?.style === "percent";

	// Steps are anchored at `min`, and the top limit is the last step below `max`.
	const anchor = Number.isFinite(min) ? min : 0;
	const decimals = Math.max(decimalsOf(step), decimalsOf(anchor));
	const lower = min;
	const upper = Number.isFinite(max)
		? Math.max(anchor + Math.floor((max - anchor) / step + 1e-9) * step, lower)
		: max;

	const snap = (raw: number) => {
		const clamped = clamp(raw, lower, upper);
		if (!Number.isFinite(clamped)) return clamped;
		// The ratio is rounded first so 0.175 / 0.05 counts as 3.5, not 3.4999….
		const steps = Math.round(Number(((clamped - anchor) / step).toFixed(9)));
		const snapped = anchor + steps * step;
		// Round to the step's precision so 0.1 + 0.2 lands on 0.3.
		return Number(clamp(snapped, lower, upper).toFixed(decimals));
	};

	const controlled = valueProp !== undefined;
	const [internalValue, setInternalValue] = useState(() => snap(defaultValue));
	const value = controlled ? snap(valueProp) : internalValue;

	// Digits roll in the direction the value moved.
	const [shown, setShown] = useState({ value, trend: 1 });
	if (shown.value !== value) {
		setShown({ value, trend: value > shown.value ? 1 : -1 });
	}

	const [draft, setDraftState] = useState<string | null>(null);
	const [holding, setHolding] = useState<Direction | null>(null);
	const [announcement, setAnnouncement] = useState("");

	const formatter = useMemo(
		() => new Intl.NumberFormat(locale, format),
		[locale, format],
	);
	const separators = useMemo(() => getSeparators(locale), [locale]);
	const formatValue = (next: number) => formatter.format(next);
	const valueText = formatValue(value);

	const draftValue =
		draft === null ? null : parseNumber(draft, separators, percent);
	const invalid =
		draft !== null &&
		draft.trim() !== "" &&
		draftValue !== null &&
		(Number.isNaN(draftValue) || snap(draftValue) !== draftValue);

	const shouldReduceMotion = useReducedMotion() ?? false;
	const { trigger: haptic } = useWebHaptics();
	const {
		click: playClick,
		pop: playPop,
		toggle: playToggle,
		warning: playWarning,
	} = useTiks({
		// Sound stays on under reduced motion; only movement is reduced.
		respectReducedMotion: false,
	});

	const inputId = useId();
	const inputRef = useRef<HTMLInputElement>(null);
	const [valueScope, animateValue] = useAnimate<HTMLDivElement>();
	const buttonRefs = useRef<Record<Direction, HTMLButtonElement | null>>({
		1: null,
		[-1]: null,
	});
	const ringRefs = useRef<Record<Direction, HTMLSpanElement | null>>({
		1: null,
		[-1]: null,
	});
	const valueRef = useRef(value);
	const draftRef = useRef<string | null>(null);
	const lastEmittedRef = useRef(value);
	const lastCueAtRef = useRef(Number.NEGATIVE_INFINITY);
	const announcedRef = useRef(valueText);
	const pressRef = useRef(false);
	const pressedButtonRef = useRef<Direction | null>(null);
	const holdRef = useRef<{
		direction: Direction;
		startedAt: number;
		repeats: number;
		accelerated: boolean;
		timer: ReturnType<typeof setTimeout>;
	} | null>(null);

	useLayoutEffect(() => {
		valueRef.current = value;
	});

	const setDraft = (next: string | null) => {
		draftRef.current = next;
		setDraftState(next);
	};

	const cue = (kind: StepKind) => {
		const now = performance.now();
		if (now - lastCueAtRef.current < CUE_THROTTLE_MS) return;
		lastCueAtRef.current = now;
		if (kind === "accelerate") {
			if (sound) playToggle(true);
			if (haptics) void haptic("light");
		} else {
			if (sound) playClick();
			if (haptics) void haptic("selection");
		}
	};

	const warn = () => {
		lastCueAtRef.current = performance.now();
		if (sound) playWarning();
		if (haptics) void haptic("warning");
	};

	// The soft wall: a pop, a rigid haptic, and a nudge toward the pressed side.
	const hitWall = (direction: Direction) => {
		lastCueAtRef.current = performance.now();
		if (sound) playPop();
		if (haptics) void haptic("rigid");
		if (shouldReduceMotion || !valueScope.current) return;
		const offsets = [0, 4, -3, 0].map(
			(offset) => offset * (horizontal ? direction : -direction),
		);
		void animateValue(
			valueScope.current,
			horizontal ? { x: offsets } : { y: offsets },
			{ duration: 0.22, ease: "easeOut" },
		);
	};

	const emit = (next: number) => {
		valueRef.current = next;
		lastEmittedRef.current = next;
		if (!controlled) setInternalValue(next);
		onValueChange?.(next);
	};

	/** Resolves a pending typed value and returns the value to build on. */
	const commitDraft = () => {
		const text = draftRef.current;
		const current = valueRef.current;
		if (text === null) return current;
		setDraft(null);
		// An emptied field goes back to the last valid value.
		if (text.trim() === "") return current;
		const parsed = parseNumber(text, separators, percent);
		if (Number.isNaN(parsed)) {
			warn();
			return current;
		}
		const next = snap(parsed);
		if (next !== parsed) warn();
		if (next !== current) {
			emit(next);
			onValueCommit?.(next);
		}
		return next;
	};

	const stepBy = (
		direction: Direction,
		multiplier = 1,
		kind: StepKind = "step",
	): StepResult => {
		const current = commitDraft();
		const next = snap(current + direction * step * multiplier);
		if (next === current) return "blocked";
		emit(next);
		const atLimit = direction > 0 ? next >= upper : next <= lower;
		if (atLimit) {
			hitWall(direction);
			return "limit";
		}
		cue(kind);
		return "moved";
	};

	const jumpTo = (target: number) => {
		const current = commitDraft();
		const next = snap(target);
		if (!Number.isFinite(next) || next === current) return;
		emit(next);
		hitWall(next > current ? 1 : -1);
		onValueCommit?.(next);
	};

	const setRing = (
		direction: Direction,
		opacity: number | number[],
		ms = 150,
	) => {
		const ring = ringRefs.current[direction];
		if (ring)
			animate(ring, { opacity }, { duration: ms / 1000, ease: "easeOut" });
	};

	// Scale is driven here rather than with `whileTap`: a button that reaches
	// its limit turns disabled mid-press and would never see the release.
	const pressButton = (direction: Direction) => {
		pressedButtonRef.current = direction;
		const button = buttonRefs.current[direction];
		if (button) animate(button, { scale: 0.92 }, pressSpring);
	};

	const releaseButton = () => {
		const direction = pressedButtonRef.current;
		if (direction === null) return;
		pressedButtonRef.current = null;
		const button = buttonRefs.current[direction];
		if (button) animate(button, { scale: 1 }, pressSpring);
	};

	const endPress = () => {
		releaseButton();
		const hold = holdRef.current;
		if (hold) {
			clearTimeout(hold.timer);
			setRing(hold.direction, 0);
			holdRef.current = null;
			setHolding(null);
		}
		if (pressRef.current) {
			pressRef.current = false;
			onValueCommit?.(valueRef.current);
		}
	};

	const repeat = () => {
		const hold = holdRef.current;
		if (!hold) return;
		hold.repeats += 1;
		const accelerated = accelerate && hold.repeats > ACCELERATE_AFTER;
		const kind = accelerated && !hold.accelerated ? "accelerate" : "step";
		hold.accelerated = accelerated;
		if (hold.repeats === 1) setHolding(hold.direction);
		const result = stepBy(hold.direction, accelerated ? largeStep : 1, kind);
		if (result !== "moved") {
			endPress();
			return;
		}
		const elapsed = performance.now() - hold.startedAt;
		const ramp = clamp(
			(elapsed - REPEAT_DELAY) / (REPEAT_RAMP_END - REPEAT_DELAY),
			0,
			1,
		);
		const interval = REPEAT_SLOW - (REPEAT_SLOW - REPEAT_FAST) * ramp;
		// The ring flashes on each repeat, so its pulse tracks the repeat rate.
		setRing(hold.direction, shouldReduceMotion ? 0.6 : [0.9, 0.25], interval);
		hold.timer = setTimeout(() => repeatRef.current(), interval);
	};

	// Timers call through refs so they always see the latest props.
	const repeatRef = useRef(repeat);
	const endPressRef = useRef(endPress);
	const wheelStepRef = useRef((steps: number) => {
		void steps;
	});
	useLayoutEffect(() => {
		repeatRef.current = repeat;
		endPressRef.current = endPress;
		wheelStepRef.current = (steps: number) => {
			const result = stepBy(steps > 0 ? 1 : -1, Math.abs(steps));
			if (result !== "blocked") onValueCommit?.(valueRef.current);
		};
	});

	const handlePointerDown = (
		direction: Direction,
		event: PointerEvent<HTMLButtonElement>,
	) => {
		if (inactive || event.button !== 0) return;
		// Touch captures the pointer implicitly; release it so sliding off cancels.
		if (event.currentTarget.hasPointerCapture(event.pointerId)) {
			event.currentTarget.releasePointerCapture(event.pointerId);
		}
		endPress();
		pressRef.current = true;
		pressButton(direction);
		if (stepBy(direction) !== "moved") return;
		holdRef.current = {
			direction,
			startedAt: performance.now(),
			repeats: 0,
			accelerated: false,
			timer: setTimeout(() => repeatRef.current(), REPEAT_DELAY),
		};
	};

	// Keyboard and assistive tech activate the buttons with a click of detail 0.
	const handleClick = (
		direction: Direction,
		event: MouseEvent<HTMLButtonElement>,
	) => {
		if (inactive || event.detail !== 0) return;
		if (stepBy(direction) !== "blocked") onValueCommit?.(valueRef.current);
	};

	const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
		if (event.key === "Escape" && draftRef.current !== null) {
			event.preventDefault();
			setDraft(null);
			return;
		}
		if (event.key === "Enter") {
			if (draftRef.current === null) return;
			event.preventDefault();
			commitDraft();
			return;
		}
		if (inactive) return;
		let direction: Direction | null = null;
		let multiplier = 1;
		switch (event.key) {
			case "ArrowUp":
				direction = 1;
				multiplier = event.shiftKey ? largeStep : 1;
				break;
			case "ArrowDown":
				direction = -1;
				multiplier = event.shiftKey ? largeStep : 1;
				break;
			case "PageUp":
				direction = 1;
				multiplier = largeStep;
				break;
			case "PageDown":
				direction = -1;
				multiplier = largeStep;
				break;
			case "Home":
				if (!Number.isFinite(lower)) return;
				event.preventDefault();
				jumpTo(lower);
				return;
			case "End":
				if (!Number.isFinite(upper)) return;
				event.preventDefault();
				jumpTo(upper);
				return;
			default:
				return;
		}
		event.preventDefault();
		if (stepBy(direction, multiplier) !== "blocked") {
			onValueCommit?.(valueRef.current);
		}
	};

	const handlePaste = (event: ClipboardEvent<HTMLInputElement>) => {
		if (inactive) return;
		event.preventDefault();
		const input = event.currentTarget;
		const pasted = normalizeNumber(
			event.clipboardData.getData("text"),
			separators,
		).replace(".", separators.decimal);
		const text = input.value;
		const start = input.selectionStart ?? text.length;
		const end = input.selectionEnd ?? text.length;
		setDraft(text.slice(0, start) + pasted + text.slice(end));
	};

	// A controlled value that changes mid-hold stops the repeat.
	useEffect(() => {
		if (holdRef.current && valueProp !== lastEmittedRef.current) {
			endPressRef.current();
		}
	}, [valueProp]);

	useEffect(() => {
		if (inactive) endPressRef.current();
	}, [inactive]);

	// Releasing outside the window never reaches the button.
	useEffect(() => {
		if (holding === null) return;
		const end = () => endPressRef.current();
		window.addEventListener("blur", end);
		return () => window.removeEventListener("blur", end);
	}, [holding]);

	useEffect(
		() => () => {
			if (holdRef.current) clearTimeout(holdRef.current.timer);
		},
		[],
	);

	// Announce once the value settles, not on every repeat. A focused
	// spinbutton already reads its own changes, so skip those.
	useEffect(() => {
		if (valueText === announcedRef.current) return;
		const timer = setTimeout(() => {
			announcedRef.current = valueText;
			if (document.activeElement !== inputRef.current) {
				setAnnouncement(valueText);
			}
		}, ANNOUNCE_DELAY);
		return () => clearTimeout(timer);
	}, [valueText]);

	// Wheel needs a non-passive listener to keep the page from scrolling.
	useEffect(() => {
		const input = inputRef.current;
		if (!input || !wheel || inactive) return;
		let accumulated = 0;
		const onWheel = (event: WheelEvent) => {
			if (document.activeElement !== input || event.deltaY === 0) return;
			event.preventDefault();
			let steps = 0;
			if (event.deltaMode !== 0 || Math.abs(event.deltaY) >= WHEEL_STEP_PX) {
				// One notch, one step.
				steps = -Math.sign(event.deltaY);
				accumulated = 0;
			} else {
				accumulated += event.deltaY;
				steps = -Math.trunc(accumulated / WHEEL_STEP_PX);
				accumulated += steps * WHEEL_STEP_PX;
			}
			if (steps !== 0) wheelStepRef.current(steps);
		};
		input.addEventListener("wheel", onWheel, { passive: false });
		return () => input.removeEventListener("wheel", onWheel);
	}, [wheel, inactive]);

	const atMin = value <= lower;
	const atMax = value >= upper;
	const typing = draft !== null;
	const sizeStyle = sizes[size];
	const variantStyle = variants[variant];
	const widthChars =
		Math.max(
			2,
			...[lower, upper, value]
				.filter(Number.isFinite)
				.map((bound) => formatValue(bound).length),
		) + 1;
	const inputMode =
		lower < 0 ? "text" : decimals > 0 && !percent ? "decimal" : "numeric";

	const renderButton = (direction: Direction) => {
		const increase = direction === 1;
		const blocked = increase ? atMax : atMin;
		const Icon = horizontal
			? increase
				? Plus
				: Minus
			: increase
				? ChevronUp
				: ChevronDown;
		return (
			<button
				ref={(node) => {
					buttonRefs.current[direction] = node;
				}}
				type="button"
				tabIndex={-1}
				aria-label={`${increase ? "Increase" : "Decrease"} ${label}`}
				aria-controls={inputId}
				disabled={inactive || blocked}
				data-slot={`number-stepper-${increase ? "increment" : "decrement"}`}
				data-holding={holding === direction || undefined}
				onPointerDown={(event) => handlePointerDown(direction, event)}
				onPointerUp={endPress}
				onPointerLeave={endPress}
				onPointerCancel={endPress}
				onClick={(event) => handleClick(direction, event)}
				// Keep focus (and any draft) in the input.
				onMouseDown={(event) => event.preventDefault()}
				onContextMenu={(event) => event.preventDefault()}
				className={cn(
					"relative inline-flex pointer-coarse:min-h-11 pointer-coarse:min-w-11 shrink-0 cursor-pointer touch-manipulation select-none items-center justify-center outline-none transition-[opacity,color,background-color] duration-150 disabled:pointer-events-none disabled:opacity-40",
					horizontal
						? sizeStyle.button[variant]
						: cn("w-full", sizeStyle.verticalButton),
					sizeStyle.icon,
					variantStyle.button,
				)}
			>
				<Icon aria-hidden />
				<span
					ref={(node) => {
						ringRefs.current[direction] = node;
					}}
					aria-hidden
					data-slot="number-stepper-ring"
					className="pointer-events-none absolute inset-0 rounded-[inherit] opacity-0 ring-2 ring-ring ring-offset-1 ring-offset-background"
				/>
			</button>
		);
	};

	return (
		<div
			dir="ltr"
			data-slot="number-stepper"
			data-variant={variant}
			data-size={size}
			data-orientation={orientation}
			data-state={holding !== null ? "holding" : typing ? "typing" : "idle"}
			data-bound={atMin ? "min" : atMax ? "max" : undefined}
			data-invalid={invalid || undefined}
			data-disabled={disabled || undefined}
			data-readonly={readOnly || undefined}
			className={cn(
				"inline-flex w-fit items-center font-medium tabular-nums data-disabled:cursor-not-allowed data-disabled:opacity-50",
				horizontal ? "flex-row gap-1" : "min-w-12 flex-col gap-0.5",
				variant === "outline" && (horizontal ? "px-1" : "py-1"),
				sizeStyle.root,
				variantStyle.root,
				className,
			)}
		>
			{renderButton(horizontal ? -1 : 1)}
			<motion.div
				ref={valueScope}
				data-slot="number-stepper-value"
				className="grid place-items-center"
			>
				<input
					ref={inputRef}
					id={inputId}
					type="text"
					role="spinbutton"
					inputMode={inputMode}
					autoComplete="off"
					autoCorrect="off"
					spellCheck={false}
					aria-label={label}
					aria-valuenow={value}
					aria-valuemin={Number.isFinite(lower) ? lower : undefined}
					aria-valuemax={Number.isFinite(upper) ? upper : undefined}
					aria-valuetext={valueText}
					aria-invalid={invalid || undefined}
					disabled={disabled}
					readOnly={readOnly}
					value={draft ?? valueText}
					onChange={(event) => setDraft(event.target.value)}
					// Show the real text where the click lands, ready to edit.
					onPointerDown={() => {
						if (!inactive && draftRef.current === null) setDraft(valueText);
					}}
					onBlur={commitDraft}
					onKeyDown={handleKeyDown}
					onPaste={handlePaste}
					style={{ width: `${widthChars}ch` }}
					className={cn(
						"col-start-1 row-start-1 h-full min-w-0 bg-transparent px-0.5 text-center outline-none disabled:cursor-not-allowed aria-invalid:text-destructive",
						!horizontal && "py-0.5",
						// While NumberFlow shows the value, the input stays invisible.
						!typing &&
							"text-transparent caret-transparent selection:bg-transparent",
						variantStyle.input,
					)}
				/>
				{typing ? null : (
					<NumberFlow
						aria-hidden
						value={value}
						locales={locale}
						format={format as Format | undefined}
						trend={shown.trend}
						animated={!shouldReduceMotion}
						respectMotionPreference={false}
						transformTiming={digitTiming}
						spinTiming={digitTiming}
						className="pointer-events-none col-start-1 row-start-1"
					/>
				)}
			</motion.div>
			{renderButton(horizontal ? 1 : -1)}
			{name ? (
				<input type="hidden" name={name} value={value} disabled={disabled} />
			) : null}
			<span aria-live="polite" aria-atomic className="sr-only">
				{announcement}
			</span>
		</div>
	);
}

"use client";

import { useTiks } from "@rexa-developer/tiks/react";
import { Ellipsis } from "lucide-react";
import {
	type AnimationPlaybackControls,
	animate,
	LayoutGroup,
	type MotionValue,
	motion,
	useMotionValue,
	useReducedMotion,
	useTransform,
} from "motion/react";
import {
	createContext,
	type FocusEvent,
	type KeyboardEvent,
	type MouseEvent,
	type PointerEvent,
	type ReactNode,
	useCallback,
	useContext,
	useEffect,
	useId,
	useLayoutEffect,
	useMemo,
	useRef,
	useState,
} from "react";
import { useWebHaptics } from "web-haptics/react";
import { cn } from "@/lib/utils";

const snapSpring = { type: "spring", stiffness: 500, damping: 40 } as const;
const armSpring = { type: "spring", stiffness: 700, damping: 35 } as const;
const collapseTransition = { duration: 0.22, ease: "easeOut" } as const;
const fadeTransition = { duration: 0.12, ease: "easeOut" } as const;
const popTransition = { duration: 0.28, ease: "easeOut" } as const;

/** Pointer travel, in px, before a gesture commits to an axis. */
const AXIS_LOCK = 8;
/** Share of the action group a release must pass to stay open. */
const REVEAL_RATIO = 0.4;
/** Release speed, in px/s, that fires the outermost action. */
const FLICK_VELOCITY = 800;
/** Fastest release, in px/s, so one jumpy pointer event can't fling the row. */
const MAX_VELOCITY = 4000;
/** Seconds of release velocity added when deciding to open or close. */
const PROJECT_SECONDS = 0.08;
/** Resistance past the furthest travel. */
const ELASTIC = 0.1;
/** Distance, in px, a drag must back off a line before it can cross again. */
const HYSTERESIS = 12;
/** Most of the row an action group may cover when revealed. */
const MAX_GROUP_RATIO = 0.75;
/** Minimum gap, in px, between the revealed actions and the arm line. */
const MIN_ARM_GAP = 32;
/** Ms after opening that pointer clicks on actions are ignored, so a double-click on ⋯ can't fire one. */
const OPEN_GUARD_MS = 350;

type Side = "leading" | "trailing";
type RowState =
	| "idle"
	| "dragging"
	| "revealed"
	| "armed"
	| "committing"
	| "collapsed"
	| "disabled";

export type SwipeActionTone = "default" | "blue" | "amber" | "destructive";

export interface SwipeAction {
	id: string;
	/** Visible label and accessible name. */
	label: string;
	icon?: ReactNode;
	tone?: SwipeActionTone;
	/** Collapse the row before calling `onAction`. */
	destructive?: boolean;
	/** Ask "Confirm?" in place before firing. */
	confirm?: boolean;
	/** Live region message once the action fires. Defaults to `label: row label`. */
	announce?: string;
	/** Rejecting springs the row back and plays an error. */
	onAction: () => void | Promise<void>;
}

export interface SwipeActionsProps {
	children: ReactNode;
	/** Revealed by swiping toward the end edge, listed from the start edge in. */
	leading?: SwipeAction[];
	/** Revealed by swiping toward the start edge, listed from the content out. */
	trailing?: SwipeAction[];
	/** Fire the outermost action on a long swipe or a fast flick. */
	fullSwipe?: boolean;
	/** Share of the row width that arms a full swipe. */
	fullSwipeThreshold?: number;
	/** Width of each action, in px. Shrinks to fit narrow rows. */
	actionWidth?: number;
	/** Show a ⋯ button on hover that reveals the actions. */
	showHandle?: boolean;
	/** Show labels under icons. Inherits from `SwipeList`. */
	showLabels?: boolean;
	/** Play a toggle when arming and a swoosh or pop when an action fires. */
	sound?: boolean;
	/** Trigger haptics on supported devices. */
	haptics?: boolean;
	disabled?: boolean;
	/** Accessible name for the row, used in announcements. */
	label: string;
	className?: string;
}

export interface SwipeListProps {
	children: ReactNode;
	/** `inset` rounded cards with a gap, or `plain` edge-to-edge rows. */
	variant?: "inset" | "plain";
	/** Show labels under icons for every row. */
	showLabels?: boolean;
	/** Accessible name for the list. */
	label?: string;
	className?: string;
}

const tones: Record<SwipeActionTone, string> = {
	default: "bg-zinc-500 text-white dark:bg-zinc-600",
	blue: "bg-blue-500 text-white",
	amber: "bg-amber-500 text-white",
	destructive: "bg-red-500 text-white",
};

type SwipeListContextValue = {
	variant: "inset" | "plain";
	showLabels: boolean;
	register: (id: string, close: () => void) => () => void;
	notifyOpen: (id: string) => void;
	announce: (message: string) => void;
};

const SwipeListContext = createContext<SwipeListContextValue | null>(null);

function clamp(value: number, min: number, max: number) {
	return Math.min(Math.max(value, min), max);
}

/** Polite status region; a counter forces repeat messages to be read again. */
function useAnnouncer() {
	const [message, setMessage] = useState({ text: "", count: 0 });
	const region = (
		<span role="status" aria-live="polite" className="sr-only">
			{message.text}
			{message.count % 2 ? "​" : ""}
		</span>
	);
	const announce = useCallback(
		(text: string) =>
			setMessage((previous) => ({ text, count: previous.count + 1 })),
		[],
	);
	return { region, announce };
}

export function SwipeList({
	children,
	variant = "plain",
	showLabels = true,
	label,
	className,
}: SwipeListProps) {
	const rowsRef = useRef(new Map<string, () => void>());
	const { region, announce } = useAnnouncer();

	const value = useMemo<SwipeListContextValue>(
		() => ({
			variant,
			showLabels,
			register: (id, close) => {
				rowsRef.current.set(id, close);
				return () => {
					rowsRef.current.delete(id);
				};
			},
			notifyOpen: (id) => {
				for (const [other, close] of rowsRef.current) {
					if (other !== id) close();
				}
			},
			announce,
		}),
		[variant, showLabels, announce],
	);

	return (
		<SwipeListContext.Provider value={value}>
			<LayoutGroup>
				<div
					role="list"
					aria-label={label}
					data-slot="swipe-list"
					data-variant={variant}
					className={cn("flex flex-col", className)}
				>
					{children}
				</div>
			</LayoutGroup>
			{region}
		</SwipeListContext.Provider>
	);
}

function ActionButton({
	action,
	side,
	count,
	sign,
	x,
	stretch,
	popScale,
	stretchTarget,
	width: actionWidth,
	showLabel,
	reduceMotion,
	confirming,
	onPress,
}: {
	action: SwipeAction;
	side: Side;
	count: number;
	sign: number;
	x: MotionValue<number>;
	stretch: MotionValue<number>;
	popScale: MotionValue<number>;
	stretchTarget: boolean;
	width: number;
	showLabel: boolean;
	reduceMotion: boolean;
	confirming: boolean;
	onPress: (event: MouseEvent<HTMLButtonElement>) => void;
}) {
	// Buttons split the revealed width; the stretch target eats the others' share.
	const width = useTransform([x, stretch], ([value, grow]: number[]) => {
		const revealed = Math.max(0, value * sign);
		if (count === 1) return revealed;
		const share = (revealed / count) * (1 - grow);
		return stretchTarget ? revealed - share * (count - 1) : share;
	});
	const progress = useTransform(width, (value) =>
		clamp(value / actionWidth, 0, 1),
	);
	const iconScale = useTransform(progress, (value) =>
		reduceMotion ? 1 : 0.6 + 0.4 * value,
	);
	const opacity = useTransform(progress, (value) => (reduceMotion ? 1 : value));

	return (
		<motion.button
			type="button"
			data-slot="swipe-actions-action"
			data-tone={action.tone ?? "default"}
			data-confirming={confirming || undefined}
			aria-label={confirming ? `Confirm ${action.label}` : undefined}
			onClick={onPress}
			style={{ width }}
			className={cn(
				"relative flex h-full min-w-0 cursor-pointer overflow-hidden outline-none focus-visible:ring-2 focus-visible:ring-white/80 focus-visible:ring-inset",
				side === "leading" ? "justify-end" : "justify-start",
				tones[action.tone ?? "default"],
			)}
		>
			<motion.span
				style={{ width: actionWidth, opacity }}
				className="flex h-full shrink-0 flex-col items-center justify-center gap-1 px-1"
			>
				{action.icon ? (
					<motion.span
						aria-hidden
						style={{ scale: iconScale }}
						className="flex [&_svg:not([class*='size-'])]:size-5"
					>
						<motion.span
							style={{ scale: stretchTarget ? popScale : 1 }}
							className="flex"
						>
							{action.icon}
						</motion.span>
					</motion.span>
				) : null}
				<span
					className={cn(
						"max-w-full truncate font-medium text-xs leading-none",
						!showLabel && !confirming && action.icon && "sr-only",
					)}
				>
					{confirming ? "Confirm?" : action.label}
				</span>
			</motion.span>
		</motion.button>
	);
}

export function SwipeActions({
	children,
	leading = [],
	trailing = [],
	fullSwipe = true,
	fullSwipeThreshold = 0.6,
	actionWidth = 76,
	showHandle = true,
	showLabels: showLabelsProp,
	sound = true,
	haptics = true,
	disabled = false,
	label,
	className,
}: SwipeActionsProps) {
	const list = useContext(SwipeListContext);
	const variant = list?.variant ?? "plain";
	const showLabels = showLabelsProp ?? list?.showLabels ?? true;
	const id = useId();
	const reduceMotion = useReducedMotion() ?? false;
	const { trigger: haptic } = useWebHaptics();
	const {
		toggle: playToggle,
		swoosh: playSwoosh,
		pop: playPop,
		error: playError,
	} = useTiks({
		// Sound stays on under reduced motion; only movement is reduced.
		respectReducedMotion: false,
	});
	const { region, announce: announceLocally } = useAnnouncer();
	const announce = list?.announce ?? announceLocally;

	const collapserRef = useRef<HTMLDivElement>(null);
	const rootRef = useRef<HTMLDivElement>(null);
	const x = useMotionValue(0);
	const stretch = useMotionValue(0);
	const popScale = useMotionValue(1);
	const surfaceOpacity = useMotionValue(1);

	const [openSide, setOpenSide] = useState<Side | null>(null);
	const [confirming, setConfirming] = useState<string | null>(null);
	const [rowWidth, setRowWidth] = useState(0);
	const [dir, setDir] = useState(1);

	const openRef = useRef<Side | null>(null);
	const busyRef = useRef(false);
	const suppressClickRef = useRef(false);
	const openedAtRef = useRef(0);
	const xAnimationRef = useRef<AnimationPlaybackControls | null>(null);
	const savedBoxRef = useRef<{
		height: number;
		paddingTop: string;
		paddingBottom: string;
	} | null>(null);
	const cuesRef = useRef({
		side: null as Side | null,
		pastReveal: false,
		armed: false,
	});
	const dragRef = useRef<{
		pointerId: number;
		startX: number;
		startY: number;
		origin: number;
		locked: boolean;
		scale: number;
	} | null>(null);

	const actionsOf = (side: Side) => (side === "leading" ? leading : trailing);
	/** +1 when the side opens by moving content right. Flips in RTL. */
	const signOf = (side: Side) => (side === "leading" ? dir : -dir);
	const sideOf = (value: number): Side | null =>
		value === 0 ? null : value * dir > 0 ? "leading" : "trailing";
	const outermostOf = (side: Side) => {
		const actions = actionsOf(side);
		return side === "leading" ? actions[0] : actions[actions.length - 1];
	};
	const widthOf = (side: Side) => {
		const count = actionsOf(side).length;
		if (!count || !rowWidth) return actionWidth;
		return Math.min(actionWidth, (rowWidth * MAX_GROUP_RATIO) / count);
	};
	const revealOf = (side: Side) => widthOf(side) * actionsOf(side).length;
	const armAtOf = (side: Side) =>
		Math.max(fullSwipeThreshold * rowWidth, revealOf(side) + MIN_ARM_GAP);

	const setRowState = (state: RowState) => {
		if (rootRef.current) rootRef.current.dataset.state = state;
	};

	const moveTo = (target: number, velocity = 0) => {
		xAnimationRef.current?.stop();
		xAnimationRef.current = null;
		if (reduceMotion) {
			if (x.get() === target) return;
			// No travel: the row reappears in place with a short fade.
			x.jump(target);
			surfaceOpacity.jump(0);
			animate(surfaceOpacity, 1, fadeTransition);
			return;
		}
		xAnimationRef.current = animate(x, target, {
			...snapSpring,
			velocity,
			restDelta: 0.5,
		});
	};

	const setStretch = (on: boolean) => {
		if (reduceMotion) stretch.jump(on ? 1 : 0);
		else animate(stretch, on ? 1 : 0, armSpring);
	};

	const pop = () => {
		if (!reduceMotion) animate(popScale, [1, 1.15, 1], popTransition);
	};

	const open = (side: Side, velocity = 0) => {
		openedAtRef.current = performance.now();
		openRef.current = side;
		setOpenSide(side);
		list?.notifyOpen(id);
		setRowState("revealed");
		moveTo(signOf(side) * revealOf(side), velocity);
	};

	const close = (velocity = 0) => {
		openRef.current = null;
		setOpenSide(null);
		setConfirming(null);
		cuesRef.current.armed = false;
		setStretch(false);
		if (!busyRef.current) setRowState("idle");
		moveTo(0, velocity);
	};

	/** Keeps focus out of a tray that is about to go inert. */
	const reclaimFocus = () => {
		const root = rootRef.current;
		if (
			root?.contains(document.activeElement) &&
			document.activeElement !== root
		)
			root.focus({ preventScroll: true });
	};

	const collapse = async () => {
		const element = collapserRef.current;
		if (!element) return;
		const style = getComputedStyle(element);
		savedBoxRef.current = {
			height: element.offsetHeight,
			paddingTop: style.paddingTop,
			paddingBottom: style.paddingBottom,
		};
		if (reduceMotion) {
			await animate(element, { opacity: 0 }, fadeTransition);
			Object.assign(element.style, {
				height: "0px",
				paddingTop: "0px",
				paddingBottom: "0px",
			});
			return;
		}
		await animate(
			element,
			{
				height: [savedBoxRef.current.height, 0],
				paddingTop: [savedBoxRef.current.paddingTop, "0px"],
				paddingBottom: [savedBoxRef.current.paddingBottom, "0px"],
				opacity: [1, 0],
			},
			collapseTransition,
		);
	};

	const expand = async () => {
		const element = collapserRef.current;
		const saved = savedBoxRef.current;
		if (!element || !saved) return;
		await animate(
			element,
			{
				height: saved.height,
				paddingTop: saved.paddingTop,
				paddingBottom: saved.paddingBottom,
				opacity: 1,
			},
			reduceMotion ? fadeTransition : collapseTransition,
		);
		for (const property of [
			"height",
			"padding-top",
			"padding-bottom",
			"opacity",
		])
			element.style.removeProperty(property);
		savedBoxRef.current = null;
	};

	const fail = (action: SwipeAction) => {
		if (sound) playError();
		if (haptics) void haptic("error");
		announce(`${action.label} failed: ${label}`);
	};

	/** The next row's root, so focus has somewhere to go when this one leaves. */
	const neighbourRow = () => {
		const item = collapserRef.current?.parentElement;
		const sibling = item?.nextElementSibling ?? item?.previousElementSibling;
		return sibling?.querySelector<HTMLElement>('[data-slot="swipe-actions"]');
	};

	const fire = async (side: Side, action: SwipeAction, velocity = 0) => {
		if (busyRef.current || disabled) return;
		const sign = signOf(side);

		if (action.confirm && confirming !== action.id) {
			// First press asks in place; the action fills the group.
			cuesRef.current.armed = false;
			openedAtRef.current = performance.now();
			setConfirming(action.id);
			openRef.current = side;
			setOpenSide(side);
			list?.notifyOpen(id);
			setRowState("revealed");
			setStretch(true);
			pop();
			if (sound) playToggle(true);
			if (haptics) void haptic("medium");
			moveTo(sign * revealOf(side), velocity);
			return;
		}

		busyRef.current = true;
		setRowState("committing");
		if (action.destructive) {
			if (sound) playPop();
			if (haptics) void haptic("rigid");
		} else {
			if (sound) playSwoosh();
			if (haptics) void haptic("success");
		}
		announce(action.announce ?? `${action.label}: ${label}`);

		if (!action.destructive) {
			reclaimFocus();
			busyRef.current = false;
			close(velocity);
			setRowState("committing");
			try {
				await action.onAction();
			} catch {
				fail(action);
			} finally {
				if (!openRef.current && !dragRef.current) setRowState("idle");
			}
			return;
		}

		const hadFocus = rootRef.current?.contains(document.activeElement);
		openRef.current = null;
		setOpenSide(null);
		setConfirming(null);
		if (!reduceMotion) {
			xAnimationRef.current?.stop();
			xAnimationRef.current = animate(x, sign * rowWidth, {
				...snapSpring,
				velocity,
			});
		}
		await collapse();
		setRowState("collapsed");
		if (hadFocus)
			(neighbourRow() ?? rootRef.current)?.focus({ preventScroll: true });
		try {
			await action.onAction();
		} catch {
			fail(action);
			xAnimationRef.current?.stop();
			x.jump(0);
			cuesRef.current.armed = false;
			stretch.jump(0);
			await expand();
			busyRef.current = false;
			setRowState("idle");
		}
	};

	// Latest handlers for the imperative listeners, so they never re-bind.
	const api = useRef({ close, track: (_value: number) => {} });
	useLayoutEffect(() => {
		api.current = {
			close,
			// Threshold cues, only while a finger or mouse drives the row.
			track: (value) => {
				if (!dragRef.current?.locked) return;
				const cues = cuesRef.current;
				const side = sideOf(value);
				if (side !== cues.side) {
					cues.side = side;
					cues.pastReveal = false;
				}
				if (!side) return;
				const distance = Math.abs(value);
				const revealLine = revealOf(side) * REVEAL_RATIO;
				if (!cues.pastReveal && distance >= revealLine) {
					cues.pastReveal = true;
					if (haptics) void haptic("selection");
				} else if (cues.pastReveal && distance < revealLine - HYSTERESIS) {
					cues.pastReveal = false;
				}
				if (!fullSwipe) return;
				const armAt = armAtOf(side);
				if (!cues.armed && distance >= armAt) {
					cues.armed = true;
					setRowState("armed");
					if (sound) playToggle(true);
					if (haptics) void haptic("medium");
					if (!reduceMotion) {
						animate(stretch, 1, armSpring);
						pop();
					}
				} else if (cues.armed && distance < armAt - HYSTERESIS) {
					cues.armed = false;
					setRowState("dragging");
					if (sound) playToggle(false);
					if (haptics) void haptic("soft");
					if (!reduceMotion) animate(stretch, 0, armSpring);
				}
			},
		};
	});

	useEffect(() => x.on("change", (value) => api.current.track(value)), [x]);

	useEffect(() => {
		if (!list) return;
		return list.register(id, () => {
			if (openRef.current) api.current.close();
		});
	}, [list, id]);

	// Row size and direction.
	useLayoutEffect(() => {
		const root = rootRef.current;
		if (!root) return;
		const measure = () => {
			setDir(getComputedStyle(root).direction === "rtl" ? -1 : 1);
			setRowWidth(root.offsetWidth);
		};
		measure();
		const observer = new ResizeObserver(measure);
		observer.observe(root);
		return () => observer.disconnect();
	}, []);

	// A resize while open keeps the actions fully revealed.
	// biome-ignore lint/correctness/useExhaustiveDependencies: only re-anchor on resize
	useEffect(() => {
		const side = openRef.current;
		if (!side || dragRef.current || busyRef.current) return;
		xAnimationRef.current?.stop();
		x.jump(signOf(side) * revealOf(side));
	}, [rowWidth, dir]);

	// Tapping elsewhere or scrolling closes an open row.
	useEffect(() => {
		if (!openSide) return;
		const onPointerDown = (event: globalThis.PointerEvent) => {
			if (!rootRef.current?.contains(event.target as Node)) api.current.close();
		};
		const onScroll = (event: Event) => {
			if (dragRef.current?.locked) return;
			if (rootRef.current?.contains(event.target as Node)) return;
			api.current.close();
		};
		document.addEventListener("pointerdown", onPointerDown, true);
		window.addEventListener("scroll", onScroll, true);
		return () => {
			document.removeEventListener("pointerdown", onPointerDown, true);
			window.removeEventListener("scroll", onScroll, true);
		};
	}, [openSide]);

	// iOS can still scroll the page under a captured pointer; block it mid-drag.
	useEffect(() => {
		const root = rootRef.current;
		if (!root) return;
		const onTouchMove = (event: TouchEvent) => {
			if (dragRef.current?.locked) event.preventDefault();
		};
		root.addEventListener("touchmove", onTouchMove, { passive: false });
		return () => root.removeEventListener("touchmove", onTouchMove);
	}, []);

	useEffect(() => () => xAnimationRef.current?.stop(), []);

	/** Follows the pointer, with resistance past the furthest travel. */
	const resist = (raw: number) => {
		const side = sideOf(raw);
		if (!side || !actionsOf(side).length) return 0;
		const sign = signOf(side);
		const distance = raw * sign;
		const max = fullSwipe ? rowWidth : revealOf(side);
		if (distance <= max) return raw;
		return sign * (reduceMotion ? max : max + (distance - max) * ELASTIC);
	};

	const release = () => {
		const value = x.get();
		const side = sideOf(value);
		const velocity = clamp(x.getVelocity(), -MAX_VELOCITY, MAX_VELOCITY);
		if (!side) return close(velocity);
		const sign = signOf(side);
		const distance = value * sign;
		const speed = velocity * sign;
		const reveal = revealOf(side);
		const outermost = outermostOf(side);
		if (
			fullSwipe &&
			outermost &&
			(cuesRef.current.armed || (speed > FLICK_VELOCITY && distance >= reveal))
		) {
			// A flick skips the arm line, so stretch the outermost action here.
			if (!cuesRef.current.armed && !reduceMotion)
				animate(stretch, 1, armSpring);
			void fire(side, outermost, velocity);
			return;
		}
		const projected = distance + speed * PROJECT_SECONDS;
		if (projected >= reveal * REVEAL_RATIO) open(side, velocity);
		else close(velocity);
	};

	const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
		if (disabled || busyRef.current || event.button !== 0 || !event.isPrimary)
			return;
		const root = event.currentTarget;
		const rect = root.getBoundingClientRect();
		dragRef.current = {
			pointerId: event.pointerId,
			startX: event.clientX,
			startY: event.clientY,
			origin: x.get(),
			locked: false,
			// CSS zoom and transforms scale client coordinates; work in local px.
			scale: rect.width / (root.offsetWidth || 1) || 1,
		};
	};

	const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
		const drag = dragRef.current;
		if (!drag || drag.pointerId !== event.pointerId) return;
		const dx = (event.clientX - drag.startX) / drag.scale;
		if (!drag.locked) {
			const dy = (event.clientY - drag.startY) / drag.scale;
			if (Math.max(Math.abs(dx), Math.abs(dy)) < AXIS_LOCK) return;
			if (Math.abs(dy) > Math.abs(dx)) {
				// Vertical: leave the gesture to the page.
				dragRef.current = null;
				return;
			}
			const root = event.currentTarget;
			root.setPointerCapture(event.pointerId);
			root.dataset.dragging = "";
			xAnimationRef.current?.stop();
			xAnimationRef.current = null;
			drag.locked = true;
			// Count travel from the lock line so a fast first move isn't lost.
			drag.startX += Math.sign(dx) * AXIS_LOCK * drag.scale;
			drag.origin = x.get();
			const side = sideOf(drag.origin);
			cuesRef.current = {
				side,
				pastReveal: side
					? Math.abs(drag.origin) >= revealOf(side) * REVEAL_RATIO
					: false,
				armed: false,
			};
			if (confirming) {
				setConfirming(null);
				setStretch(false);
			}
			setRowState("dragging");
		}
		x.set(resist(drag.origin + (event.clientX - drag.startX) / drag.scale));
	};

	const endDrag = (event: PointerEvent<HTMLDivElement>) => {
		const drag = dragRef.current;
		if (!drag || drag.pointerId !== event.pointerId) return;
		dragRef.current = null;
		if (!drag.locked) return;
		const root = event.currentTarget;
		if (root.hasPointerCapture(event.pointerId))
			root.releasePointerCapture(event.pointerId);
		delete root.dataset.dragging;
		// The click that follows a drag belongs to the drag.
		suppressClickRef.current = true;
		setTimeout(() => {
			suppressClickRef.current = false;
		}, 0);
		release();
	};

	const handleClickCapture = (event: MouseEvent<HTMLDivElement>) => {
		if (!suppressClickRef.current) return;
		suppressClickRef.current = false;
		event.preventDefault();
		event.stopPropagation();
	};

	// A tap on the content of an open row closes it instead of activating it.
	const handleContentClickCapture = (event: MouseEvent<HTMLDivElement>) => {
		if (!openRef.current || event.detail === 0) return;
		event.preventDefault();
		event.stopPropagation();
		close();
	};

	const sideFor = (push: number): Side =>
		push * dir > 0 ? "leading" : "trailing";
	const handleSide: Side | null = trailing.length
		? "trailing"
		: leading.length
			? "leading"
			: null;

	const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
		if (disabled || busyRef.current) return;
		const root = event.currentTarget;
		const target = event.target as HTMLElement;
		if (event.key === "Escape" && openRef.current) {
			event.preventDefault();
			close();
			root.focus({ preventScroll: true });
			return;
		}
		const fromRow = target === root;
		const fromTray = !!target.closest('[data-slot="swipe-actions-tray"]');
		if (!fromRow && !fromTray) return;

		if (event.key === "ArrowRight" || event.key === "ArrowLeft") {
			const push = event.key === "ArrowRight" ? 1 : -1;
			const current = openRef.current;
			if (current) {
				if (signOf(current) === push) return;
				event.preventDefault();
				close();
				root.focus({ preventScroll: true });
				return;
			}
			const side = sideFor(push);
			if (!actionsOf(side).length) return;
			event.preventDefault();
			open(side);
			return;
		}

		if (event.key === "Delete" || event.key === "Backspace") {
			const candidates = (["trailing", "leading"] as const).flatMap((side) =>
				actionsOf(side).map((action) => ({ side, action })),
			);
			const match =
				candidates.find(
					({ action }) => action.destructive && action.tone === "destructive",
				) ?? candidates.find(({ action }) => action.destructive);
			if (!match) return;
			event.preventDefault();
			void fire(match.side, match.action);
		}
	};

	const handleBlur = (event: FocusEvent<HTMLDivElement>) => {
		const next = event.relatedTarget as Node | null;
		if (next && !event.currentTarget.contains(next) && openRef.current) close();
	};

	const renderTray = (side: Side) => {
		const actions = actionsOf(side);
		if (!actions.length) return null;
		const sign = signOf(side);
		const width = widthOf(side);
		const outermost = outermostOf(side);
		const isOpen = openSide === side;
		return (
			<Tray
				id={`${id}-${side}`}
				side={side}
				sign={sign}
				x={x}
				inert={!isOpen || disabled}
				className={tones[outermost?.tone ?? "default"]}
			>
				{actions.map((action) => (
					<ActionButton
						key={action.id}
						action={action}
						side={side}
						count={actions.length}
						sign={sign}
						x={x}
						stretch={stretch}
						popScale={popScale}
						stretchTarget={
							confirming && isOpen
								? confirming === action.id
								: action === outermost
						}
						width={width}
						showLabel={showLabels}
						reduceMotion={reduceMotion}
						confirming={isOpen && confirming === action.id}
						onPress={(event) => {
							// Keyboard clicks have no detail and are never accidental.
							if (
								event.detail > 0 &&
								performance.now() - openedAtRef.current < OPEN_GUARD_MS
							)
								return;
							void fire(side, action);
						}}
					/>
				))}
			</Tray>
		);
	};

	return (
		<motion.div
			layout={list && !reduceMotion ? "position" : undefined}
			role={list ? "listitem" : undefined}
			data-slot="swipe-actions-item"
			className="group/swipe-item"
		>
			<div
				ref={collapserRef}
				className={cn(
					"overflow-hidden",
					variant === "inset" && "pb-2 group-last/swipe-item:pb-0",
				)}
			>
				<div
					ref={rootRef}
					role="group"
					aria-label={label}
					tabIndex={disabled ? -1 : 0}
					data-slot="swipe-actions"
					data-state={disabled ? "disabled" : "idle"}
					data-variant={variant}
					data-open={openSide ?? undefined}
					data-disabled={disabled || undefined}
					onPointerDown={handlePointerDown}
					onPointerMove={handlePointerMove}
					onPointerUp={endDrag}
					onPointerCancel={endDrag}
					onClickCapture={handleClickCapture}
					onKeyDown={handleKeyDown}
					onBlur={handleBlur}
					className={cn(
						"group/swipe relative isolate touch-pan-y overflow-hidden outline-none focus-visible:outline-2 focus-visible:outline-ring focus-visible:-outline-offset-2 data-dragging:cursor-grabbing data-dragging:select-none data-disabled:opacity-60",
						variant === "inset"
							? "rounded-xl border bg-card text-card-foreground shadow-xs"
							: "border-b bg-background group-last/swipe-item:border-b-0",
						className,
					)}
				>
					<motion.div style={{ opacity: surfaceOpacity }} className="relative">
						{renderTray("leading")}
						{renderTray("trailing")}
						<motion.div
							data-slot="swipe-actions-content"
							onClickCapture={handleContentClickCapture}
							style={{ x }}
							className="relative z-10 bg-inherit will-change-transform"
						>
							{children}
							{showHandle && handleSide && !disabled ? (
								<button
									type="button"
									tabIndex={-1}
									data-slot="swipe-actions-handle"
									aria-expanded={openSide !== null}
									aria-controls={`${id}-${openSide ?? handleSide}`}
									aria-label={
										openSide
											? `Hide actions for ${label}`
											: `Show actions for ${label}`
									}
									onClick={() => (openSide ? close() : open(handleSide))}
									className="absolute end-2 top-1/2 flex size-7 -translate-y-1/2 cursor-pointer items-center justify-center rounded-full border bg-background text-muted-foreground opacity-0 shadow-xs outline-none transition-[opacity,color] duration-150 hover:text-foreground focus-visible:opacity-100 group-hover/swipe:opacity-100 group-data-dragging/swipe:opacity-0 [@media(hover:none)]:sr-only"
								>
									<Ellipsis aria-hidden className="size-4" />
								</button>
							) : null}
						</motion.div>
					</motion.div>
				</div>
			</div>
			{list ? null : region}
		</motion.div>
	);
}

function Tray({
	id,
	side,
	sign,
	x,
	inert,
	className,
	children,
}: {
	id: string;
	side: Side;
	sign: number;
	x: MotionValue<number>;
	inert: boolean;
	className?: string;
	children: ReactNode;
}) {
	const width = useTransform(x, (value) => Math.max(0, value * sign));
	return (
		<motion.div
			id={id}
			inert={inert}
			data-slot="swipe-actions-tray"
			data-side={side}
			style={{ width }}
			className={cn(
				"absolute inset-y-0 flex overflow-hidden",
				side === "leading" ? "start-0" : "end-0",
				className,
			)}
		>
			{children}
		</motion.div>
	);
}

"use client";

import { Dialog as DialogPrimitive } from "@base-ui/react/dialog";
import { useTiks } from "@rexa-developer/tiks/react";
import { XIcon } from "lucide-react";
import {
	type AnimationPlaybackControls,
	animate,
	type MotionValue,
	motion,
	useMotionValue,
	useReducedMotion,
	useTransform,
} from "motion/react";
import {
	type ComponentProps,
	createContext,
	type KeyboardEvent,
	type MouseEvent,
	type PointerEvent,
	type ReactNode,
	type RefObject,
	useCallback,
	useContext,
	useEffect,
	useLayoutEffect,
	useRef,
	useState,
	useSyncExternalStore,
} from "react";
import { useWebHaptics } from "web-haptics/react";
import { cn } from "@/lib/utils";

const settleSpring = {
	type: "spring",
	stiffness: 400,
	damping: 40,
	mass: 0.9,
} as const;
const openSpring = { type: "spring", stiffness: 320, damping: 34 } as const;
const reducedTween = {
	type: "tween",
	duration: 0.12,
	ease: "easeOut",
} as const;

/** Seconds of release velocity projected ahead before picking a snap point. */
const PROJECTION_SECONDS = 0.2;
/** Downward release speed, in px/s, that closes the sheet from its lowest snap. */
const DISMISS_VELOCITY = 1000;
/** Fastest release, in px/s, so one jumpy pointer event can't fling the sheet. */
const MAX_VELOCITY = 4000;
/** Share of the pointer's travel past full height that the sheet follows. */
const RUBBER_BAND = 0.3;
/** Px past full height where the rubber band hits its limit. */
const RUBBER_LIMIT = 16;
/** Px band around a snap point a drag must clear before it counts as crossed. */
const DETENT_HYSTERESIS = 6;
/** Pointer travel, in px, before a press turns into a drag or a scroll. */
const DRAG_SLOP = 4;
/** Px kept free above the sheet at full height. Matches the height classes. */
const TOP_GAP = 24;
/** Px around the floating variant. Matches its inset classes. */
const FLOATING_INSET = 8;
/** Px past the bottom edge a closed sheet rests at, so its shadow is hidden too. */
const CLOSED_OVERSHOOT = 24;
/** Px from a target where a settling sheet counts as landed for its cue. */
const LANDING_DISTANCE = 2;
const BACKGROUND_SCALE = 0.94;
const BACKGROUND_RADIUS = 12;
const BACKGROUND_OFFSET = 10;
/** Off-screen until the first measure, so the sheet never flashes at full height. */
const UNMEASURED_Y = 10_000;
const NO_DRAG_SELECTOR =
	"input, textarea, select, [contenteditable=''], [contenteditable='true'], [data-sheet-no-drag]";
const DEFAULT_SNAP_POINTS: SnapPoint[] = [0.5, 1];

/** A fraction of the viewport height, or a px string such as `"148px"`. */
export type SnapPoint = number | `${number}px`;
type DesktopMode = "bottom" | "dialog" | "sheet";
type Phase =
	| "closed"
	| "opening"
	| "open"
	| "dragging"
	| "settling"
	| "closing";
type CloseCue = "flick" | "plain" | null;
type Layout = {
	/** `y` of each snap point; 0 is full height. */
	snaps: number[];
	/** `y` with the sheet fully off-screen. */
	closed: number;
	/** Height of the sheet element. */
	max: number;
};
type Drag = {
	pointerId: number;
	startX: number;
	startY: number;
	startSheetY: number;
	scale: number;
	scroller: HTMLElement | null;
	decided: "sheet" | "none" | null;
	fromLowest: boolean;
	hitLimit: boolean;
	sides: number[];
};

export interface SnapSheetProps {
	/** Controlled open state. */
	open?: boolean;
	/** Initial open state when uncontrolled. */
	defaultOpen?: boolean;
	onOpenChange?: (open: boolean) => void;
	/**
	 * Heights the sheet rests at, lowest first. Numbers are fractions of the
	 * viewport height and px strings are fixed heights. `1` is as tall as the
	 * sheet gets: the viewport less a 24 px gap.
	 */
	snapPoints?: SnapPoint[];
	/** Controlled index into `snapPoints`. */
	activeSnap?: number;
	/** Snap point the sheet opens to when uncontrolled. */
	defaultSnap?: number;
	/** Called when a drag, key press, or handle tap picks a new snap point. */
	onSnapChange?: (index: number) => void;
	/**
	 * Dim the page, trap focus, and lock scroll. Turn it off for map- or
	 * player-style sheets that leave the page interactive.
	 */
	modal?: boolean;
	/** Let a downward drag, a flick, Esc, or an overlay click close the sheet. */
	dismissible?: boolean;
	/** Scale `[data-sheet-wrapper]` back as the sheet reaches full height. */
	scaleBackground?: boolean;
	/** How the sheet renders from the `md` breakpoint up. */
	desktop?: DesktopMode;
	/** Only start drags from `SnapSheet.Handle`. */
	handleOnly?: boolean;
	/** Play a click per snap, a pop at full height, and a swoosh on open and dismiss. */
	sound?: boolean;
	/** Trigger haptics on supported devices. */
	haptics?: boolean;
	/** Play cues for open and snap changes that come from props too. */
	soundOnProgrammatic?: boolean;
	children?: ReactNode;
}

type SnapSheetContextValue = {
	y: MotionValue<number>;
	overlayOpacity: MotionValue<number>;
	dialogScale: MotionValue<number>;
	progress: MotionValue<number>;
	sheetX: MotionValue<string>;
	mode: DesktopMode;
	modal: boolean;
	snapIndex: number;
	snapCount: number;
	snapLabel: string;
	announcement: string;
	setPopup: (node: HTMLDivElement | null) => void;
	containerRef: RefObject<HTMLElement | null>;
	floatingRef: RefObject<boolean>;
	shouldMoveFocus: () => boolean;
	stepSnap: (index: number) => void;
	handlePointerDown: (event: PointerEvent<HTMLDivElement>) => void;
	consumeClick: () => boolean;
};

const SnapSheetContext = createContext<SnapSheetContextValue | null>(null);

function useSnapSheet() {
	const context = useContext(SnapSheetContext);
	if (!context) {
		throw new Error("SnapSheet parts must be rendered inside <SnapSheet>.");
	}
	return context;
}

function clamp(value: number, min: number, max: number) {
	return Math.min(Math.max(value, min), max);
}

function toPx(point: SnapPoint, frame: number) {
	return typeof point === "number" ? point * frame : Number.parseFloat(point);
}

function describeSnap(points: SnapPoint[], index: number) {
	const point = points[index];
	const last = index === points.length - 1;
	if (typeof point === "number") {
		if (last && point >= 0.85) return "Full height";
		if (Math.abs(point - 0.5) < 0.05) return "Half height";
		if (index === 0) return "Peek height";
		return `${Math.round(point * 100)}% height`;
	}
	if (index === 0) return "Peek height";
	if (last) return "Full height";
	return `Height ${index + 1} of ${points.length}`;
}

/** Which side of `snap` a sheet at `y` sits on: -1 above, 1 below, 0 inside the band. */
function sideOf(y: number, snap: number) {
	if (y < snap - DETENT_HYSTERESIS / 2) return -1;
	if (y > snap + DETENT_HYSTERESIS / 2) return 1;
	return 0;
}

/** The nearest element between `target` and `sheet` that scrolls vertically. */
function findScroller(target: Element, sheet: HTMLElement) {
	let node: Element | null = target;
	while (node && node !== sheet) {
		if (node instanceof HTMLElement && node.scrollHeight > node.clientHeight) {
			const { overflowY } = getComputedStyle(node);
			if (overflowY === "auto" || overflowY === "scroll") return node;
		}
		node = node.parentElement;
	}
	return null;
}

function resolveContainer(
	container: HTMLElement | RefObject<HTMLElement | null> | null | undefined,
) {
	if (!container) return null;
	return container instanceof HTMLElement ? container : container.current;
}

function subscribeDesktop(onChange: () => void) {
	const query = window.matchMedia("(min-width: 768px)");
	query.addEventListener("change", onChange);
	return () => query.removeEventListener("change", onChange);
}

function useIsDesktop() {
	return useSyncExternalStore(
		subscribeDesktop,
		() => window.matchMedia("(min-width: 768px)").matches,
		() => false,
	);
}

function SnapSheet({
	open: openProp,
	defaultOpen = false,
	onOpenChange,
	snapPoints = DEFAULT_SNAP_POINTS,
	activeSnap,
	defaultSnap = 0,
	onSnapChange,
	modal = true,
	dismissible = true,
	scaleBackground = false,
	desktop = "bottom",
	handleOnly = false,
	sound = true,
	haptics = true,
	soundOnProgrammatic = false,
	children,
}: SnapSheetProps) {
	const snapCount = Math.max(1, snapPoints.length);
	const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen);
	const open = openProp ?? uncontrolledOpen;
	// Stays mounted through the close animation, then unmounts.
	const [rendered, setRendered] = useState(open);
	if (open && !rendered) setRendered(true);

	const [uncontrolledSnap, setUncontrolledSnap] = useState(defaultSnap);
	const snapIndex = clamp(activeSnap ?? uncontrolledSnap, 0, snapCount - 1);
	const [announcement, setAnnouncement] = useState("");
	const [popup, setPopupState] = useState<HTMLDivElement | null>(null);

	const isDesktop = useIsDesktop();
	const mode: DesktopMode = isDesktop ? desktop : "bottom";
	const shouldReduceMotion = useReducedMotion() ?? false;
	const { trigger: haptic } = useWebHaptics();
	const {
		click: playClick,
		pop: playPop,
		swoosh: playSwoosh,
	} = useTiks({
		// Sound stays on under reduced motion; only movement is reduced.
		respectReducedMotion: false,
	});

	const y = useMotionValue(UNMEASURED_Y);
	const progress = useMotionValue(0);
	const popupRef = useRef<HTMLDivElement | null>(null);
	const containerRef = useRef<HTMLElement | null>(null);
	const floatingRef = useRef(false);
	const wrapperRef = useRef<HTMLElement | null>(null);
	const directionRef = useRef(1);
	const phaseRef = useRef<Phase>("closed");
	const layoutRef = useRef<Layout | null>(null);
	const animationRef = useRef<AnimationPlaybackControls | null>(null);
	const dragRef = useRef<Drag | null>(null);
	/** Snap index the sheet rests at or is heading to. */
	const indexRef = useRef(snapIndex);
	/** Snap index the sheet last came to rest at, for "settled somewhere new". */
	const settledIndexRef = useRef(snapIndex);
	const landingRef = useRef<{ y: number; index: number } | null>(null);
	const userOpenRef = useRef(false);
	const suppressClickRef = useRef(false);

	// Latest values for the imperative handlers below, so they never re-bind.
	const latest = useRef({
		open,
		snapPoints,
		snapIndex,
		activeSnap,
		defaultSnap,
		mode,
		modal,
		dismissible,
		scaleBackground,
		handleOnly,
		sound,
		haptics,
		soundOnProgrammatic,
		shouldReduceMotion,
		onOpenChange,
		onSnapChange,
	});
	useLayoutEffect(() => {
		latest.current = {
			open,
			snapPoints,
			snapIndex,
			activeSnap,
			defaultSnap,
			mode,
			modal,
			dismissible,
			scaleBackground,
			handleOnly,
			sound,
			haptics,
			soundOnProgrammatic,
			shouldReduceMotion,
			onOpenChange,
			onSnapChange,
		};
	});

	const overlayOpacity = useTransform(() => {
		const value = y.get();
		const amount = progress.get();
		const layout = layoutRef.current;
		if (latest.current.mode !== "bottom") return amount;
		if (!layout) return 0;
		const top = layout.snaps[layout.snaps.length - 1] ?? 0;
		// Modal sheets dim from closed; non-modal ones only near full height.
		const from =
			latest.current.modal || layout.snaps.length < 2
				? layout.closed
				: (layout.snaps[layout.snaps.length - 2] ?? layout.closed);
		return clamp((from - value) / (from - top || 1), 0, 1);
	});
	const dialogScale = useTransform(progress, [0, 1], [0.96, 1]);
	const sheetX = useTransform(
		() => `${(1 - progress.get()) * 100 * directionRef.current}%`,
	);

	const setPhase = useCallback((phase: Phase) => {
		phaseRef.current = phase;
		if (popupRef.current) popupRef.current.dataset.sheetState = phase;
	}, []);

	const setPopup = useCallback((node: HTMLDivElement | null) => {
		popupRef.current = node;
		if (node) node.dataset.sheetState = phaseRef.current;
		setPopupState(node);
	}, []);

	const measure = useCallback(() => {
		const element = popupRef.current;
		if (!element) return null;
		const max = element.offsetHeight;
		const inset = floatingRef.current ? FLOATING_INSET : 0;
		const frame = max + TOP_GAP + inset;
		const snaps = latest.current.snapPoints.map(
			(point) => max - clamp(toPx(point, frame), 0, max),
		);
		if (snaps.length === 0) snaps.push(0);
		layoutRef.current = { snaps, closed: max + inset + CLOSED_OVERSHOOT, max };
		directionRef.current =
			getComputedStyle(element).direction === "rtl" ? -1 : 1;
		return layoutRef.current;
	}, []);

	const stop = useCallback(() => {
		animationRef.current?.stop();
		animationRef.current = null;
	}, []);

	const runTo = useCallback(
		(
			value: MotionValue<number>,
			to: number,
			transition: typeof settleSpring | typeof openSpring,
			velocity: number,
			onComplete: () => void,
		) => {
			stop();
			if (value.get() === to) {
				onComplete();
				return;
			}
			animationRef.current = animate(value, to, {
				...(latest.current.shouldReduceMotion
					? reducedTween
					: { ...transition, velocity }),
				restDelta: 0.5,
				onComplete: () => {
					animationRef.current = null;
					onComplete();
				},
			});
		},
		[stop],
	);

	const playSnapCue = useCallback(
		(index: number) => {
			const { sound, haptics, snapPoints } = latest.current;
			const top = index === snapPoints.length - 1;
			if (sound) (top ? playPop : playClick)();
			if (haptics) void haptic(top ? "light" : "selection");
		},
		[haptic, playClick, playPop],
	);

	const resetWrapper = useCallback(() => {
		const wrapper = wrapperRef.current;
		if (!wrapper) return;
		wrapper.style.removeProperty("transform");
		wrapper.style.removeProperty("transform-origin");
		wrapper.style.removeProperty("border-radius");
		wrapper.style.removeProperty("overflow");
		wrapper.style.removeProperty("will-change");
		wrapperRef.current = null;
	}, []);

	const attachWrapper = useCallback(() => {
		resetWrapper();
		const { scaleBackground, shouldReduceMotion, mode } = latest.current;
		if (!scaleBackground || shouldReduceMotion || mode !== "bottom") return;
		const root = containerRef.current ?? document;
		const wrapper = root.querySelector<HTMLElement>("[data-sheet-wrapper]");
		if (!wrapper) return;
		wrapper.style.transformOrigin = "center top";
		wrapper.style.willChange = "transform";
		wrapperRef.current = wrapper;
	}, [resetWrapper]);

	const animateOpen = useCallback(
		(cue: boolean) => {
			const layout = measure();
			if (!layout) return;
			const fromClosed = phaseRef.current === "closed";
			const index = clamp(latest.current.snapIndex, 0, layout.snaps.length - 1);
			indexRef.current = index;
			settledIndexRef.current = index;
			landingRef.current = null;
			attachWrapper();
			setPhase("opening");
			if (latest.current.mode === "bottom") {
				if (fromClosed) y.jump(layout.closed);
				progress.jump(1);
				runTo(y, layout.snaps[index] ?? 0, openSpring, 0, () =>
					setPhase("open"),
				);
			} else {
				y.jump(0);
				if (fromClosed) progress.jump(0);
				runTo(progress, 1, openSpring, 0, () => setPhase("open"));
			}
			if (cue && latest.current.sound) playSwoosh();
		},
		[attachWrapper, measure, playSwoosh, progress, runTo, setPhase, y],
	);

	const animateClose = useCallback(
		(velocity: number, cue: CloseCue) => {
			const finish = () => {
				setPhase("closed");
				resetWrapper();
				// A controlled parent can refuse to close; come back up.
				if (latest.current.open) {
					animateOpen(false);
					return;
				}
				setRendered(false);
				// Uncontrolled sheets open at their default snap point again.
				if (latest.current.activeSnap === undefined) {
					const index = clamp(
						latest.current.defaultSnap,
						0,
						latest.current.snapPoints.length - 1,
					);
					indexRef.current = index;
					setUncontrolledSnap(index);
				}
			};
			landingRef.current = null;
			setPhase("closing");
			const layout = layoutRef.current;
			if (latest.current.mode === "bottom" && layout) {
				runTo(y, layout.closed, openSpring, velocity, finish);
			} else {
				runTo(progress, 0, openSpring, 0, finish);
			}
			if (cue) {
				if (latest.current.sound) playSwoosh();
				if (cue === "flick" && latest.current.haptics) void haptic("nudge");
			}
		},
		[
			animateOpen,
			haptic,
			playSwoosh,
			progress,
			resetWrapper,
			runTo,
			setPhase,
			y,
		],
	);

	const setOpen = useCallback((next: boolean) => {
		if (latest.current.open === next) return;
		setUncontrolledOpen(next);
		latest.current.onOpenChange?.(next);
	}, []);

	const requestClose = useCallback(
		(cue: CloseCue, velocity = 0) => {
			const phase = phaseRef.current;
			if (phase === "closed" || phase === "closing") return;
			setOpen(false);
			animateClose(velocity, cue);
		},
		[animateClose, setOpen],
	);

	const settle = useCallback(
		(index: number, { velocity = 0, cue = false } = {}) => {
			const layout = layoutRef.current;
			if (!layout) return;
			const target = layout.snaps[index] ?? 0;
			indexRef.current = index;
			landingRef.current =
				cue && index !== settledIndexRef.current ? { y: target, index } : null;
			setPhase("settling");
			runTo(y, target, settleSpring, velocity, () => {
				settledIndexRef.current = index;
				setPhase("open");
				const landing = landingRef.current;
				if (landing) {
					landingRef.current = null;
					playSnapCue(landing.index);
				}
			});
		},
		[playSnapCue, runTo, setPhase, y],
	);

	/** Moves to a snap picked by the user and reports it. */
	const commitSnap = useCallback(
		(index: number, velocity = 0) => {
			settle(index, { velocity, cue: true });
			if (index === latest.current.snapIndex) return;
			setUncontrolledSnap(index);
			setAnnouncement(
				`Sheet at ${describeSnap(latest.current.snapPoints, index).toLowerCase()}`,
			);
			latest.current.onSnapChange?.(index);
		},
		[settle],
	);

	// Open and close from state, whether it changed here or through props.
	useLayoutEffect(() => {
		if (!popup) return;
		const phase = phaseRef.current;
		if (open) {
			if (phase === "closed" || phase === "closing") {
				const cue = userOpenRef.current || latest.current.soundOnProgrammatic;
				animateOpen(cue);
			}
			return;
		}
		if (phase === "closed") {
			setRendered(false);
		} else if (phase !== "closing") {
			animateClose(0, latest.current.soundOnProgrammatic ? "plain" : null);
		}
	}, [open, popup, animateOpen, animateClose]);

	// Controlled snap: glide there, unless a drag is in progress (the drag wins).
	useEffect(() => {
		if (activeSnap === undefined) return;
		const phase = phaseRef.current;
		if (phase === "dragging" || phase === "closed" || phase === "closing") {
			return;
		}
		const index = clamp(activeSnap, 0, snapCount - 1);
		if (index === indexRef.current) return;
		settle(index, { cue: latest.current.soundOnProgrammatic });
	}, [activeSnap, snapCount, settle]);

	// The one place that reacts to movement: detents, the rubber band,
	// landing cues, and the background scale.
	useEffect(() => {
		const sync = (value: number) => {
			const layout = layoutRef.current;
			if (!layout) return;
			const { haptics } = latest.current;
			const landing = landingRef.current;
			if (landing && Math.abs(value - landing.y) < LANDING_DISTANCE) {
				landingRef.current = null;
				playSnapCue(landing.index);
			}

			const top = layout.snaps[layout.snaps.length - 1] ?? 0;
			const drag = dragRef.current;
			if (phaseRef.current === "dragging" && drag) {
				if (!drag.hitLimit && value < top - RUBBER_LIMIT) {
					drag.hitLimit = true;
					if (haptics) void haptic("rigid");
				}
				let crossed = false;
				layout.snaps.forEach((snap, index) => {
					const side = sideOf(value, snap);
					if (side === 0 || side === drag.sides[index]) return;
					if (drag.sides[index] !== 0) crossed = true;
					drag.sides[index] = side;
				});
				if (crossed && haptics) void haptic("soft");
			}

			const wrapper = wrapperRef.current;
			if (!wrapper) return;
			const from =
				layout.snaps.length > 1
					? (layout.snaps[layout.snaps.length - 2] ?? layout.closed)
					: layout.closed;
			const amount = clamp((from - value) / (from - top || 1), 0, 1);
			if (amount === 0) {
				wrapper.style.removeProperty("transform");
				wrapper.style.removeProperty("border-radius");
				wrapper.style.removeProperty("overflow");
				return;
			}
			const scale = 1 - (1 - BACKGROUND_SCALE) * amount;
			wrapper.style.transform = `translateY(${BACKGROUND_OFFSET * amount}px) scale(${scale})`;
			wrapper.style.borderRadius = `${BACKGROUND_RADIUS * amount}px`;
			wrapper.style.overflow = "hidden";
		};
		return y.on("change", sync);
	}, [haptic, playSnapCue, y]);

	// Recompute snap px on resize, rotation, and the iOS address bar.
	useLayoutEffect(() => {
		if (!popup) return;
		let lastHeight = popup.offsetHeight;
		const observer = new ResizeObserver(() => {
			if (latest.current.mode !== "bottom") return;
			if (popup.offsetHeight === lastHeight) return;
			lastHeight = popup.offsetHeight;
			const layout = measure();
			if (!layout) return;
			const target = layout.snaps[indexRef.current] ?? 0;
			const phase = phaseRef.current;
			if (phase === "open") {
				y.jump(target);
			} else if (phase === "opening" || phase === "settling") {
				runTo(y, target, settleSpring, y.getVelocity(), () => setPhase("open"));
			}
		});
		observer.observe(popup);
		return () => observer.disconnect();
	}, [popup, measure, runTo, setPhase, y]);

	// Keep the sheet above the virtual keyboard.
	useEffect(() => {
		const viewport = window.visualViewport;
		if (!popup || !viewport || containerRef.current) return;
		const update = () => {
			const keyboard =
				viewport.scale > 1.01
					? 0
					: Math.max(
							0,
							Math.round(
								window.innerHeight - viewport.height - viewport.offsetTop,
							),
						);
			popup.style.setProperty("--snap-sheet-keyboard", `${keyboard}px`);
		};
		update();
		viewport.addEventListener("resize", update);
		viewport.addEventListener("scroll", update);
		return () => {
			viewport.removeEventListener("resize", update);
			viewport.removeEventListener("scroll", update);
		};
	}, [popup]);

	// Switching between bottom and desktop layouts while open.
	useLayoutEffect(() => {
		const phase = phaseRef.current;
		if (phase === "closed" || phase === "closing") return;
		stop();
		attachWrapper();
		if (mode === "bottom") {
			const layout = measure();
			progress.jump(1);
			if (layout) y.jump(layout.snaps[indexRef.current] ?? 0);
		} else {
			y.jump(0);
			progress.jump(1);
		}
		setPhase("open");
	}, [mode, attachWrapper, measure, progress, setPhase, stop, y]);

	useEffect(
		() => () => {
			stop();
			resetWrapper();
		},
		[stop, resetWrapper],
	);

	const beginDrag = useCallback(
		(drag: Drag, clientY: number) => {
			const layout = layoutRef.current;
			const sheet = popupRef.current;
			if (!layout || !sheet) return;
			stop();
			landingRef.current = null;
			drag.startY = clientY;
			drag.startSheetY = y.get();
			drag.sides = layout.snaps.map((snap) => sideOf(drag.startSheetY, snap));
			setPhase("dragging");
			try {
				sheet.setPointerCapture(drag.pointerId);
			} catch {
				// The pointer may already be gone.
			}
			window.getSelection()?.removeAllRanges();
			suppressClickRef.current = true;
		},
		[setPhase, stop, y],
	);

	/** Settles on the first move past the slop: the sheet drags or the content scrolls. */
	const decide = useCallback(
		(drag: Drag, clientX: number, clientY: number) => {
			const dx = clientX - drag.startX;
			const dy = clientY - drag.startY;
			if (Math.abs(dx) < DRAG_SLOP && Math.abs(dy) < DRAG_SLOP) return;
			// Axis lock: sideways swipes belong to carousels and the browser.
			if (Math.abs(dx) > Math.abs(dy)) {
				drag.decided = "none";
				return;
			}
			const layout = layoutRef.current;
			const top = layout?.snaps[layout.snaps.length - 1] ?? 0;
			const atFull = y.get() <= top + 1;
			const scroller = drag.scroller;
			const scrolls = scroller && (dy < 0 || scroller.scrollTop > 0);
			drag.decided = atFull && scrolls ? "none" : "sheet";
			if (drag.decided === "sheet") beginDrag(drag, clientY);
		},
		[beginDrag, y],
	);

	const release = useCallback(
		(drag: Drag) => {
			const layout = layoutRef.current;
			if (!layout) return;
			const { dismissible } = latest.current;
			const velocity = clamp(y.getVelocity(), -MAX_VELOCITY, MAX_VELOCITY);
			const current = y.get();
			const lowest = layout.snaps[0] ?? 0;
			if (
				dismissible &&
				velocity > DISMISS_VELOCITY &&
				(drag.fromLowest || current >= lowest)
			) {
				requestClose("flick", velocity);
				return;
			}
			const projected = current + velocity * PROJECTION_SECONDS;
			let nearest = 0;
			layout.snaps.forEach((snap, index) => {
				if (
					Math.abs(snap - projected) <
					Math.abs((layout.snaps[nearest] ?? 0) - projected)
				) {
					nearest = index;
				}
			});
			const nearestDistance = Math.abs(
				(layout.snaps[nearest] ?? 0) - projected,
			);
			if (
				dismissible &&
				Math.abs(layout.closed - projected) < nearestDistance
			) {
				requestClose("flick", Math.max(velocity, 0));
				return;
			}
			commitSnap(nearest, velocity);
		},
		[commitSnap, requestClose, y],
	);

	const handlePointerDown = useCallback(
		(event: PointerEvent<HTMLDivElement>) => {
			const { mode, handleOnly } = latest.current;
			if (mode !== "bottom" || !event.isPrimary) return;
			if (event.pointerType === "mouse" && event.button !== 0) return;
			const phase = phaseRef.current;
			if (phase === "closed" || phase === "closing") return;
			const target = event.target as HTMLElement;
			const sheet = event.currentTarget;
			const onHandle = Boolean(
				target.closest("[data-slot='snap-sheet-handle']"),
			);
			if (handleOnly && !onHandle) return;
			if (!onHandle && target.closest(NO_DRAG_SELECTOR)) return;
			const rect = sheet.getBoundingClientRect();
			suppressClickRef.current = false;
			dragRef.current = {
				pointerId: event.pointerId,
				startX: event.clientX,
				startY: event.clientY,
				startSheetY: y.get(),
				// CSS zoom and transforms scale client coordinates; work in local px.
				scale: rect.height / (sheet.offsetHeight || 1) || 1,
				scroller: onHandle ? null : findScroller(target, sheet),
				decided: null,
				fromLowest: settledIndexRef.current === 0,
				hitLimit: false,
				sides: [],
			};
		},
		[y],
	);

	// Follow the gesture on window: before it's decided, the pointer can leave
	// the sheet, and capturing on press would retarget clicks inside it.
	useEffect(() => {
		if (!popup) return;
		const onPointerMove = (event: globalThis.PointerEvent) => {
			const drag = dragRef.current;
			if (!drag || drag.pointerId !== event.pointerId) return;
			if (drag.decided === null) decide(drag, event.clientX, event.clientY);
			if (drag.decided !== "sheet") return;
			const layout = layoutRef.current;
			if (!layout) return;
			const raw = drag.startSheetY + (event.clientY - drag.startY) / drag.scale;
			const top = layout.snaps[layout.snaps.length - 1] ?? 0;
			const lowest = layout.snaps[0] ?? 0;
			let next = raw;
			if (raw < top) {
				next = top - (top - raw) * RUBBER_BAND;
			} else if (!latest.current.dismissible && raw > lowest) {
				next = lowest + (raw - lowest) * RUBBER_BAND;
			}
			y.set(Math.min(next, layout.closed));
		};
		const onPointerUp = (event: globalThis.PointerEvent) => {
			const drag = dragRef.current;
			if (!drag || drag.pointerId !== event.pointerId) return;
			dragRef.current = null;
			if (popup.hasPointerCapture(event.pointerId)) {
				popup.releasePointerCapture(event.pointerId);
			}
			if (drag.decided === "sheet") release(drag);
		};
		window.addEventListener("pointermove", onPointerMove);
		window.addEventListener("pointerup", onPointerUp);
		window.addEventListener("pointercancel", onPointerUp);
		return () => {
			window.removeEventListener("pointermove", onPointerMove);
			window.removeEventListener("pointerup", onPointerUp);
			window.removeEventListener("pointercancel", onPointerUp);
		};
	}, [popup, decide, release, y]);

	// iOS and Android start scrolling unless the first touchmove is cancelled.
	useEffect(() => {
		if (!popup) return;
		const onTouchMove = (event: TouchEvent) => {
			const drag = dragRef.current;
			const touch = event.touches[0];
			if (!drag || !touch) return;
			if (drag.decided === null) decide(drag, touch.clientX, touch.clientY);
			if (drag.decided === "sheet" && event.cancelable) event.preventDefault();
		};
		popup.addEventListener("touchmove", onTouchMove, { passive: false });
		return () => popup.removeEventListener("touchmove", onTouchMove);
	}, [popup, decide]);

	const stepSnap = useCallback(
		(index: number) => {
			const phase = phaseRef.current;
			if (phase === "closed" || phase === "closing" || phase === "dragging") {
				return;
			}
			commitSnap(clamp(index, 0, latest.current.snapPoints.length - 1));
		},
		[commitSnap],
	);

	const consumeClick = useCallback(() => {
		const suppressed = suppressClickRef.current;
		suppressClickRef.current = false;
		return suppressed;
	}, []);

	const shouldMoveFocus = useCallback(
		() => latest.current.modal || userOpenRef.current,
		[],
	);

	const handleOpenChange = useCallback(
		(next: boolean, details: DialogPrimitive.Root.ChangeEventDetails) => {
			if (next) {
				userOpenRef.current = true;
				setOpen(true);
				return;
			}
			const userDismissal =
				details.reason === "escape-key" || details.reason === "outside-press";
			if (userDismissal && !latest.current.dismissible) return;
			requestClose("plain");
		},
		[requestClose, setOpen],
	);

	// Opens that don't come through the trigger stay silent and keep focus.
	useLayoutEffect(() => {
		if (!open) userOpenRef.current = false;
	}, [open]);

	return (
		<SnapSheetContext.Provider
			value={{
				y,
				overlayOpacity,
				dialogScale,
				progress,
				sheetX,
				mode,
				modal,
				snapIndex,
				snapCount,
				snapLabel: describeSnap(snapPoints, snapIndex),
				announcement,
				setPopup,
				containerRef,
				floatingRef,
				shouldMoveFocus,
				stepSnap,
				handlePointerDown,
				consumeClick,
			}}
		>
			<DialogPrimitive.Root
				open={rendered}
				onOpenChange={handleOpenChange}
				modal={modal}
				disablePointerDismissal={!modal || !dismissible}
			>
				{children}
			</DialogPrimitive.Root>
		</SnapSheetContext.Provider>
	);
}

function SnapSheetTrigger(props: DialogPrimitive.Trigger.Props) {
	return <DialogPrimitive.Trigger data-slot="snap-sheet-trigger" {...props} />;
}

export interface SnapSheetContentProps {
	className?: string;
	overlayClassName?: string;
	/**
	 * Element to render into instead of `document.body`, such as a phone frame.
	 * Give it `position: relative` and `overflow: clip`.
	 */
	container?: HTMLElement | RefObject<HTMLElement | null> | null;
	/** `attached` spans the width with rounded top corners; `floating` is inset and fully rounded. */
	variant?: "attached" | "floating";
	children?: ReactNode;
}

function SnapSheetContent({
	className,
	overlayClassName,
	container,
	variant = "attached",
	children,
}: SnapSheetContentProps) {
	const {
		y,
		overlayOpacity,
		dialogScale,
		progress,
		sheetX,
		mode,
		modal,
		announcement,
		setPopup,
		containerRef,
		floatingRef,
		shouldMoveFocus,
		handlePointerDown,
	} = useSnapSheet();
	const contained = Boolean(container);
	const floating = variant === "floating";

	useLayoutEffect(() => {
		containerRef.current = resolveContainer(container);
		floatingRef.current = floating;
	});

	const style =
		mode === "dialog"
			? { opacity: progress, scale: dialogScale }
			: mode === "sheet"
				? { x: sheetX }
				: { y };

	return (
		<DialogPrimitive.Portal container={container}>
			<DialogPrimitive.Backdrop
				data-slot="snap-sheet-overlay"
				forceRender
				render={<motion.div style={{ opacity: overlayOpacity }} />}
				className={cn(
					"inset-0 z-50 bg-black/40",
					contained ? "absolute" : "fixed",
					!modal && "pointer-events-none",
					overlayClassName,
				)}
			/>
			<DialogPrimitive.Popup
				ref={setPopup}
				data-slot="snap-sheet-content"
				data-mode={mode}
				data-variant={variant}
				aria-modal={modal || undefined}
				initialFocus={shouldMoveFocus}
				render={<motion.div style={style} />}
				onPointerDown={handlePointerDown}
				className={cn(
					"group/sheet z-50 flex flex-col overscroll-contain border border-border/70 bg-background text-foreground outline-none",
					contained ? "absolute" : "fixed",
					mode === "bottom" && [
						"touch-none will-change-transform data-[sheet-state=dragging]:select-none",
						"shadow-[0_-12px_40px_-16px_rgb(0_0_0/0.35)]",
						floating
							? "inset-x-2 bottom-2 mx-auto max-w-xl rounded-[28px]"
							: "inset-x-0 bottom-0 mx-auto w-full max-w-xl rounded-t-[22px] border-b-0",
						contained
							? floating
								? "h-[calc(100%-32px)]"
								: "h-[calc(100%-24px)]"
							: floating
								? "mb-[var(--snap-sheet-keyboard,0px)] h-[calc(100dvh-32px-var(--snap-sheet-keyboard,0px))]"
								: "mb-[var(--snap-sheet-keyboard,0px)] h-[calc(100dvh-24px-var(--snap-sheet-keyboard,0px))]",
					],
					mode === "dialog" &&
						"top-1/2 left-1/2 max-h-[calc(100dvh-4rem)] w-[calc(100%-2rem)] max-w-lg -translate-x-1/2 -translate-y-1/2 rounded-2xl pt-4 shadow-2xl",
					mode === "sheet" &&
						"inset-y-0 end-0 w-full max-w-md border-y-0 border-e-0 pt-4 shadow-2xl",
					className,
				)}
			>
				{children}
				<span aria-live="polite" className="sr-only">
					{announcement}
				</span>
			</DialogPrimitive.Popup>
		</DialogPrimitive.Portal>
	);
}

function SnapSheetHandle({
	className,
	onClick,
	onKeyDown,
	...props
}: Omit<ComponentProps<"button">, "children">) {
	const { mode, snapIndex, snapCount, snapLabel, stepSnap, consumeClick } =
		useSnapSheet();
	if (mode !== "bottom") return null;

	const handleClick = (event: MouseEvent<HTMLButtonElement>) => {
		onClick?.(event);
		if (consumeClick() || event.defaultPrevented) return;
		// Tapping or pressing Enter cycles through the snap points.
		stepSnap((snapIndex + 1) % snapCount);
	};

	const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
		onKeyDown?.(event);
		if (event.defaultPrevented) return;
		const targets: Record<string, number> = {
			ArrowUp: snapIndex + 1,
			ArrowRight: snapIndex + 1,
			ArrowDown: snapIndex - 1,
			ArrowLeft: snapIndex - 1,
			Home: 0,
			End: snapCount - 1,
		};
		const target = targets[event.key];
		if (target === undefined) return;
		event.preventDefault();
		stepSnap(target);
	};

	return (
		<button
			type="button"
			role="slider"
			aria-label="Resize sheet"
			aria-orientation="vertical"
			aria-valuemin={0}
			aria-valuemax={snapCount - 1}
			aria-valuenow={snapIndex}
			aria-valuetext={snapLabel}
			data-slot="snap-sheet-handle"
			onClick={handleClick}
			onKeyDown={handleKeyDown}
			className={cn(
				"group/handle mx-auto flex h-6 w-16 shrink-0 cursor-grab touch-none items-center justify-center rounded-full outline-none focus-visible:ring-3 focus-visible:ring-ring/50 group-data-[sheet-state=dragging]/sheet:cursor-grabbing",
				className,
			)}
			{...props}
		>
			<span className="h-[5px] w-9 rounded-full bg-muted-foreground/35 transition-[width,background-color] duration-200 ease-out group-hover/handle:bg-muted-foreground/50 group-data-[sheet-state=dragging]/sheet:w-11 group-data-[sheet-state=dragging]/sheet:bg-muted-foreground/60" />
		</button>
	);
}

function SnapSheetTitle({ className, ...props }: DialogPrimitive.Title.Props) {
	return (
		<DialogPrimitive.Title
			data-slot="snap-sheet-title"
			className={cn("font-semibold text-base text-foreground", className)}
			{...props}
		/>
	);
}

function SnapSheetDescription({
	className,
	...props
}: DialogPrimitive.Description.Props) {
	return (
		<DialogPrimitive.Description
			data-slot="snap-sheet-description"
			className={cn("text-muted-foreground text-sm", className)}
			{...props}
		/>
	);
}

function SnapSheetClose({
	className,
	children,
	...props
}: DialogPrimitive.Close.Props) {
	return (
		<DialogPrimitive.Close
			data-slot="snap-sheet-close"
			className={cn(
				!children &&
					"inline-flex size-8 cursor-pointer items-center justify-center rounded-full bg-muted text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-3 focus-visible:ring-ring/50",
				className,
			)}
			{...props}
		>
			{children ?? (
				<>
					<XIcon className="size-4" />
					<span className="sr-only">Close</span>
				</>
			)}
		</DialogPrimitive.Close>
	);
}

SnapSheet.Trigger = SnapSheetTrigger;
SnapSheet.Content = SnapSheetContent;
SnapSheet.Handle = SnapSheetHandle;
SnapSheet.Title = SnapSheetTitle;
SnapSheet.Description = SnapSheetDescription;
SnapSheet.Close = SnapSheetClose;

export {
	SnapSheet,
	SnapSheetClose,
	SnapSheetContent,
	SnapSheetDescription,
	SnapSheetHandle,
	SnapSheetTitle,
	SnapSheetTrigger,
};

"use client";

import { useTiks } from "@rexa-developer/tiks/react";
import {
	AnimatePresence,
	type AnimationPlaybackControls,
	animate,
	motion,
	useMotionValue,
	useReducedMotion,
} from "motion/react";
import {
	type KeyboardEvent,
	memo,
	type PointerEvent,
	useCallback,
	useEffect,
	useLayoutEffect,
	useRef,
	useState,
} from "react";
import { useWebHaptics } from "web-haptics/react";
import { cn } from "@/lib/utils";

const landingSpring = { type: "spring", stiffness: 420, damping: 38 } as const;
const digitTransition = { duration: 0.18, ease: [0.23, 1, 0.32, 1] } as const;

/** Seconds of release velocity that a flick coasts before it snaps. */
const COAST_SECONDS = 0.25;
/** Fastest release, in px/s, so one jumpy pointer event can't fling the range. */
const MAX_VELOCITY = 4000;
/** Furthest the strip travels past a bound, in px. */
const MAX_OVERSHOOT = 40;
/** Minimum ms between step sounds and haptics. */
const TICK_THROTTLE_MS = 35;
/** Pointer travel, in px, below which a press counts as a tap. */
const TAP_SLOP = 5;
/** Ranges with more ticks than this render only the ticks near the needle. */
const WINDOW_THRESHOLD = 400;

const sizes = {
	sm: { spacing: 8, track: "h-14", readout: "text-3xl", unit: "text-sm" },
	md: { spacing: 10, track: "h-16", readout: "text-5xl", unit: "text-base" },
	lg: { spacing: 12, track: "h-20", readout: "text-6xl", unit: "text-lg" },
} as const;

type Orientation = "horizontal" | "vertical";
type RulerState = "idle" | "dragging" | "coasting";

export interface TickRulerProps {
	/** Controlled value. */
	value?: number;
	/** Initial value when uncontrolled; double-click resets to it. */
	defaultValue?: number;
	/** Called every time the needle crosses onto a new step. */
	onValueChange?: (value: number) => void;
	/** Called once the ruler settles after a drag, flick, key, wheel, or preset. */
	onValueCommit?: (value: number) => void;
	min?: number;
	max?: number;
	step?: number;
	/** Steps between medium ticks. */
	majorEvery?: number;
	/** Steps between labelled ticks. */
	labelEvery?: number;
	/** Pixels between ticks. Defaults by `size`. */
	spacing?: number;
	/** Unit shown after the readout, e.g. `min`. */
	unit?: string;
	/** Formats the readout and `aria-valuetext`. */
	format?: (value: number) => string;
	/** Values shown as chips that glide the ruler to them. */
	presets?: number[];
	/** Play a click per step and a pop at the bounds. */
	sound?: boolean;
	/** Trigger haptics on supported devices. */
	haptics?: boolean;
	disabled?: boolean;
	/** Accessible name for the slider. */
	label?: string;
	className?: string;
	size?: keyof typeof sizes;
	orientation?: Orientation;
	/** Show the large value readout above the ruler. */
	showValue?: boolean;
}

function decimalsOf(value: number) {
	const text = String(value);
	if (text.includes("e-")) return Number(text.split("e-")[1]);
	return text.split(".")[1]?.length ?? 0;
}

function clamp(value: number, min: number, max: number) {
	return Math.min(Math.max(value, min), max);
}

/** Pulls travel past a bound back so it never exceeds `MAX_OVERSHOOT`. */
function rubberBand(position: number, maxPosition: number) {
	if (position < 0) {
		const over = -position;
		return -(MAX_OVERSHOOT * over) / (over + MAX_OVERSHOOT);
	}
	if (position > maxPosition) {
		const over = position - maxPosition;
		return maxPosition + (MAX_OVERSHOOT * over) / (over + MAX_OVERSHOOT);
	}
	return position;
}

type DigitSlot = { char: string; id: number };

let nextDigitId = 0;

/** Aligns `text` to `previous` from the right, keeping ids of unchanged chars. */
function toSlots(text: string, previous: DigitSlot[]): DigitSlot[] {
	const chars = text.split("");
	return chars.map((char, index) => {
		const match = previous[previous.length - chars.length + index];
		if (match?.char === char) return match;
		nextDigitId += 1;
		return { char, id: nextDigitId };
	});
}

function RollingValue({
	text,
	direction,
	animated,
}: {
	text: string;
	direction: number;
	animated: boolean;
}) {
	// Each slot gets a fresh key whenever its character changes. Reusing a key
	// while its previous copy is still exiting can leave the digit hidden.
	const [slots, setSlots] = useState(() => toSlots(text, []));
	const [previousText, setPreviousText] = useState(text);
	if (text !== previousText) {
		setPreviousText(text);
		setSlots((previous) => toSlots(text, previous));
	}

	if (!animated) return <span>{text}</span>;

	return (
		<span className="inline-flex">
			{slots.map(({ char, id }, index) => (
				// Keyed from the right so units digits stay put as the width changes.
				<span key={slots.length - index} className="relative inline-block">
					<AnimatePresence mode="popLayout" initial={false} custom={direction}>
						<motion.span
							key={id}
							custom={direction}
							className="inline-block"
							variants={{
								enter: (d: number) => ({ y: d * 12, opacity: 0 }),
								center: { y: 0, opacity: 1 },
								exit: (d: number) => ({ y: d * -12, opacity: 0 }),
							}}
							initial="enter"
							animate="center"
							exit="exit"
							transition={digitTransition}
						>
							{char}
						</motion.span>
					</AnimatePresence>
				</span>
			))}
		</span>
	);
}

const TickStrip = memo(function TickStrip({
	start,
	end,
	spacing,
	sign,
	orientation,
	majorEvery,
	labelEvery,
	labelAt,
}: {
	start: number;
	end: number;
	spacing: number;
	sign: number;
	orientation: Orientation;
	majorEvery: number;
	labelEvery: number;
	labelAt: (index: number) => string;
}) {
	const horizontal = orientation === "horizontal";
	const ticks = [];
	for (let index = start; index <= end; index++) {
		const kind =
			index % labelEvery === 0
				? "label"
				: index % majorEvery === 0
					? "major"
					: "minor";
		const offset = sign * index * spacing;
		ticks.push(
			<span
				key={index}
				data-kind={kind}
				className={cn(
					"absolute flex items-center gap-1.5",
					horizontal
						? "top-0 -translate-x-1/2 flex-col"
						: "left-0 -translate-y-1/2 flex-row",
				)}
				style={horizontal ? { left: offset } : { top: offset }}
			>
				<span
					className={cn(
						"rounded-full",
						horizontal ? "w-px" : "h-px",
						kind === "minor" && "bg-muted-foreground/35",
						kind === "minor" && (horizontal ? "h-3" : "w-3"),
						kind === "major" && "bg-muted-foreground/60",
						kind === "major" && (horizontal ? "h-5" : "w-5"),
						kind === "label" && "bg-foreground/80",
						kind === "label" &&
							(horizontal ? "h-7 w-[1.5px]" : "h-[1.5px] w-7"),
					)}
				/>
				{kind === "label" ? (
					<span className="font-medium text-[11px] text-muted-foreground tabular-nums leading-none">
						{labelAt(index)}
					</span>
				) : null}
			</span>,
		);
	}
	return <>{ticks}</>;
});

export function TickRuler({
	value: valueProp,
	defaultValue,
	onValueChange,
	onValueCommit,
	min = 0,
	max = 100,
	step = 1,
	majorEvery = 5,
	labelEvery = 10,
	spacing: spacingProp,
	unit,
	format,
	presets,
	sound = true,
	haptics = true,
	disabled = false,
	label = "Value",
	className,
	size = "md",
	orientation = "horizontal",
	showValue = true,
}: TickRulerProps) {
	const sizeStyle = sizes[size];
	const spacing = spacingProp ?? sizeStyle.spacing;
	const horizontal = orientation === "horizontal";
	const decimals = Math.max(decimalsOf(step), decimalsOf(min));
	const maxIndex = Math.max(0, Math.round((max - min) / step));
	const maxPosition = maxIndex * spacing;

	const indexToValue = useCallback(
		(index: number) => Number((min + index * step).toFixed(decimals)),
		[min, step, decimals],
	);
	const valueToIndex = useCallback(
		(value: number) => clamp(Math.round((value - min) / step), 0, maxIndex),
		[min, step, maxIndex],
	);
	const formatValue = useCallback(
		(value: number) => (format ? format(value) : value.toFixed(decimals)),
		[format, decimals],
	);

	const initialIndex = valueToIndex(valueProp ?? defaultValue ?? min);
	const [currentIndex, setCurrentIndex] = useState(initialIndex);
	const [direction, setDirection] = useState(1);
	const [sign, setSign] = useState(horizontal ? 1 : -1);
	const [range, setRange] = useState(() =>
		maxIndex + 1 <= WINDOW_THRESHOLD
			? { start: 0, end: maxIndex }
			: {
					start: Math.max(0, initialIndex - 60),
					end: Math.min(maxIndex, initialIndex + 60),
				},
	);

	const shouldReduceMotion = useReducedMotion() ?? false;
	const { trigger: haptic } = useWebHaptics();
	const { click: playClick, pop: playPop } = useTiks({
		// Sound stays on under reduced motion; only movement is reduced.
		respectReducedMotion: false,
	});

	const rootRef = useRef<HTMLDivElement>(null);
	const trackRef = useRef<HTMLDivElement>(null);
	const position = useMotionValue(initialIndex * spacing);
	const stripOffset = useMotionValue(0);
	const centerRef = useRef(0);
	const indexRef = useRef(initialIndex);
	const animationRef = useRef<AnimationPlaybackControls | null>(null);
	const silentRef = useRef(false);
	const interactingRef = useRef(false);
	const lastTickAtRef = useRef(Number.NEGATIVE_INFINITY);
	const chunkRef = useRef(-1);
	const wheelRef = useRef({ accumulated: 0, target: initialIndex });
	const dragRef = useRef<{
		pointerId: number;
		start: number;
		startPosition: number;
		moved: boolean;
		scale: number;
	} | null>(null);

	// Latest values for the imperative listeners below, so they never re-bind.
	const latest = useRef({
		sound,
		haptics,
		onValueChange,
		onValueCommit,
		indexToValue,
		maxIndex,
		maxPosition,
		spacing,
		sign,
		labelEvery,
	});
	useLayoutEffect(() => {
		latest.current = {
			sound,
			haptics,
			onValueChange,
			onValueCommit,
			indexToValue,
			maxIndex,
			maxPosition,
			spacing,
			sign,
			labelEvery,
		};
	});

	const setRulerState = useCallback((state: RulerState) => {
		if (rootRef.current) rootRef.current.dataset.state = state;
	}, []);

	const updateRange = useCallback((pos: number) => {
		const { maxIndex, spacing } = latest.current;
		if (maxIndex + 1 <= WINDOW_THRESHOLD) {
			if (chunkRef.current !== 0) {
				chunkRef.current = 0;
				setRange({ start: 0, end: maxIndex });
			}
			return;
		}
		const visible = Math.ceil((centerRef.current * 2) / spacing) || 60;
		const chunkSize = Math.max(40, visible);
		const chunk = Math.floor(pos / spacing / chunkSize);
		if (chunk === chunkRef.current) return;
		chunkRef.current = chunk;
		setRange({
			start: Math.max(0, (chunk - 1) * chunkSize),
			end: Math.min(maxIndex, (chunk + 2) * chunkSize),
		});
	}, []);

	// The one place that reacts to movement: transforms, ticks, and feedback.
	useEffect(() => {
		const sync = (pos: number) => {
			const {
				sign,
				spacing,
				maxIndex,
				indexToValue,
				labelEvery,
				sound,
				haptics,
				onValueChange,
			} = latest.current;
			stripOffset.set(centerRef.current - sign * pos);
			updateRange(pos);

			const index = clamp(Math.round(pos / spacing), 0, maxIndex);
			const previous = indexRef.current;
			if (index === previous) return;
			indexRef.current = index;
			setCurrentIndex(index);
			setDirection(index > previous ? 1 : -1);
			if (silentRef.current) return;

			onValueChange?.(indexToValue(index));
			const now = performance.now();
			const atBound = index === 0 || index === maxIndex;
			// Bounds always sound so a fast flick still ends on the pop.
			if (!atBound && now - lastTickAtRef.current < TICK_THROTTLE_MS) return;
			lastTickAtRef.current = now;
			if (atBound) {
				if (sound) playPop();
				if (haptics) void haptic("rigid");
			} else {
				if (sound) playClick();
				if (haptics)
					void haptic(index % labelEvery === 0 ? "light" : "selection");
			}
		};
		sync(position.get());
		return position.on("change", sync);
	}, [haptic, playClick, playPop, position, stripOffset, updateRange]);

	// Track size and direction.
	useLayoutEffect(() => {
		const track = trackRef.current;
		if (!track) return;
		const measure = () => {
			const rtl = getComputedStyle(track).direction === "rtl";
			const nextSign = horizontal ? (rtl ? -1 : 1) : -1;
			latest.current.sign = nextSign;
			setSign(nextSign);
			centerRef.current =
				(horizontal ? track.offsetWidth : track.offsetHeight) / 2;
			chunkRef.current = -1;
			stripOffset.set(centerRef.current - nextSign * position.get());
			updateRange(position.get());
		};
		measure();
		const observer = new ResizeObserver(measure);
		observer.observe(track);
		return () => observer.disconnect();
	}, [horizontal, position, stripOffset, updateRange]);

	// Spacing or range changes keep the current step under the needle.
	// biome-ignore lint/correctness/useExhaustiveDependencies: re-run when the range changes too
	useEffect(() => {
		chunkRef.current = -1;
		position.jump(indexRef.current * spacing);
	}, [position, spacing, maxIndex]);

	const stop = useCallback(() => {
		animationRef.current?.stop();
		animationRef.current = null;
	}, []);

	const settle = useCallback(
		(
			targetIndex: number,
			{
				velocity = 0,
				silent = false,
				onLand,
			}: { velocity?: number; silent?: boolean; onLand?: () => void } = {},
		) => {
			stop();
			const target = clamp(targetIndex, 0, latest.current.maxIndex);
			const targetPosition = target * latest.current.spacing;
			silentRef.current = silent;
			const finish = () => {
				animationRef.current = null;
				silentRef.current = false;
				setRulerState("idle");
				if (!silent) {
					latest.current.onValueCommit?.(latest.current.indexToValue(target));
					onLand?.();
				}
			};
			if (shouldReduceMotion || position.get() === targetPosition) {
				position.jump(targetPosition);
				finish();
				return;
			}
			setRulerState("coasting");
			animationRef.current = animate(position, targetPosition, {
				...landingSpring,
				velocity,
				restDelta: 0.01,
				onComplete: finish,
			});
		},
		[position, setRulerState, shouldReduceMotion, stop],
	);

	// Controlled value: glide there silently unless the user is interacting.
	useEffect(() => {
		if (valueProp === undefined || interactingRef.current) return;
		const target = valueToIndex(valueProp);
		if (target === indexRef.current && !animationRef.current) return;
		if (animationRef.current && !silentRef.current) return;
		settle(target, { silent: true });
	}, [valueProp, valueToIndex, settle]);

	useEffect(() => stop, [stop]);

	const pointerAxis = (event: PointerEvent) =>
		horizontal ? event.clientX : event.clientY;

	const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
		if (disabled || event.button !== 0) return;
		const track = event.currentTarget;
		track.setPointerCapture(event.pointerId);
		track.focus({ preventScroll: true });
		stop();
		silentRef.current = false;
		interactingRef.current = true;
		const rect = track.getBoundingClientRect();
		// CSS zoom and transforms scale client coordinates; work in local px.
		const scale = horizontal
			? rect.width / (track.offsetWidth || 1)
			: rect.height / (track.offsetHeight || 1);
		dragRef.current = {
			pointerId: event.pointerId,
			start: pointerAxis(event),
			startPosition: position.get(),
			moved: false,
			scale: scale || 1,
		};
	};

	const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
		const drag = dragRef.current;
		if (!drag || drag.pointerId !== event.pointerId) return;
		const delta = (pointerAxis(event) - drag.start) / drag.scale;
		if (!drag.moved) {
			if (Math.abs(delta) < TAP_SLOP) return;
			drag.moved = true;
			setRulerState("dragging");
		}
		const raw = drag.startPosition - sign * delta;
		position.set(rubberBand(raw, maxPosition));
	};

	const handlePointerUp = (event: PointerEvent<HTMLDivElement>) => {
		const drag = dragRef.current;
		if (!drag || drag.pointerId !== event.pointerId) return;
		dragRef.current = null;
		interactingRef.current = false;
		const track = event.currentTarget;
		if (track.hasPointerCapture(event.pointerId)) {
			track.releasePointerCapture(event.pointerId);
		}

		if (!drag.moved) {
			// Tap: glide to the tick under the pointer.
			const rect = track.getBoundingClientRect();
			const local =
				(pointerAxis(event) - (horizontal ? rect.left : rect.top)) / drag.scale;
			const offset = sign * (local - centerRef.current);
			settle(Math.round((position.get() + offset) / spacing));
			return;
		}

		const velocity = clamp(position.getVelocity(), -MAX_VELOCITY, MAX_VELOCITY);
		const current = position.get();
		const coast = shouldReduceMotion ? 0 : velocity * COAST_SECONDS;
		const target = clamp(current + coast, 0, maxPosition);
		settle(Math.round(target / spacing), { velocity });
	};

	const handlePointerCancel = (event: PointerEvent<HTMLDivElement>) => {
		if (dragRef.current?.pointerId !== event.pointerId) return;
		dragRef.current = null;
		interactingRef.current = false;
		settle(Math.round(clamp(position.get(), 0, maxPosition) / spacing));
	};

	const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
		if (disabled) return;
		const stepBy = event.shiftKey ? 10 : 1;
		const flip = horizontal && sign < 0 ? -1 : 1;
		// Repeated keys build on the pending target, not the moving needle.
		const from = animationRef.current
			? wheelRef.current.target
			: indexRef.current;
		let target: number | null = null;
		switch (event.key) {
			case "ArrowRight":
				target = from + stepBy * flip;
				break;
			case "ArrowLeft":
				target = from - stepBy * flip;
				break;
			case "ArrowUp":
				target = from + stepBy;
				break;
			case "ArrowDown":
				target = from - stepBy;
				break;
			case "PageUp":
				target = from + 10;
				break;
			case "PageDown":
				target = from - 10;
				break;
			case "Home":
				target = 0;
				break;
			case "End":
				target = maxIndex;
				break;
			default:
				return;
		}
		event.preventDefault();
		target = clamp(target, 0, maxIndex);
		wheelRef.current.target = target;
		settle(target);
	};

	// Wheel needs a non-passive listener to keep the page from scrolling.
	useEffect(() => {
		const track = trackRef.current;
		if (!track || disabled) return;
		const onWheel = (event: WheelEvent) => {
			const { sign, maxIndex, spacing } = latest.current;
			const along = horizontal ? event.deltaX : event.deltaY;
			const across = horizontal ? event.deltaY : event.deltaX;
			let delta = 0;
			if (Math.abs(along) >= Math.abs(across)) {
				delta = sign * along;
			} else if (horizontal && document.activeElement === track) {
				// A plain mouse wheel only drives a focused horizontal ruler.
				delta = -across;
			} else {
				return;
			}
			event.preventDefault();
			const wheel = wheelRef.current;
			if (!animationRef.current) wheel.target = indexRef.current;
			let steps = 0;
			if (event.deltaMode !== 0 || Math.abs(delta) >= 50) {
				// One notch, one step.
				steps = Math.sign(delta);
				wheel.accumulated = 0;
			} else {
				wheel.accumulated += delta;
				steps = Math.trunc(wheel.accumulated / spacing);
				wheel.accumulated -= steps * spacing;
			}
			if (steps === 0) return;
			const target = clamp(wheel.target + steps, 0, maxIndex);
			if (target === wheel.target) return;
			wheel.target = target;
			settle(target);
		};
		track.addEventListener("wheel", onWheel, { passive: false });
		return () => track.removeEventListener("wheel", onWheel);
	}, [disabled, horizontal, settle]);

	// iOS can still scroll the page under a captured pointer; block it mid-drag.
	useEffect(() => {
		const track = trackRef.current;
		if (!track) return;
		const onTouchMove = (event: TouchEvent) => {
			if (dragRef.current?.moved) event.preventDefault();
		};
		track.addEventListener("touchmove", onTouchMove, { passive: false });
		return () => track.removeEventListener("touchmove", onTouchMove);
	}, []);

	const currentValue = indexToValue(currentIndex);
	const valueText = format
		? format(currentValue)
		: `${formatValue(currentValue)}${unit ? ` ${unit}` : ""}`;
	const labelAt = useCallback(
		(index: number) => indexToValue(index).toFixed(decimals),
		[indexToValue, decimals],
	);
	const defaultIndex = valueToIndex(defaultValue ?? min);

	return (
		<div
			ref={rootRef}
			data-slot="tick-ruler"
			data-state="idle"
			data-orientation={orientation}
			data-disabled={disabled || undefined}
			data-bound={
				currentIndex === 0
					? "min"
					: currentIndex === maxIndex
						? "max"
						: undefined
			}
			className={cn(
				"group/ruler flex select-none gap-4 [--tick-ruler-accent:var(--color-orange-500)] data-disabled:opacity-50",
				horizontal ? "w-full flex-col items-center" : "flex-row items-center",
				className,
			)}
		>
			{showValue ? (
				<div
					aria-hidden
					data-slot="tick-ruler-value"
					className={cn(
						"flex items-baseline gap-1.5 font-semibold text-foreground tabular-nums tracking-tight",
						sizeStyle.readout,
					)}
				>
					<RollingValue
						text={formatValue(currentValue)}
						direction={direction}
						animated={!shouldReduceMotion}
					/>
					{unit && !format ? (
						<span
							className={cn(
								"font-medium text-muted-foreground tracking-normal",
								sizeStyle.unit,
							)}
						>
							{unit}
						</span>
					) : null}
				</div>
			) : null}

			<div
				ref={trackRef}
				role="slider"
				tabIndex={disabled ? -1 : 0}
				aria-label={label}
				aria-orientation={orientation}
				aria-valuemin={min}
				aria-valuemax={max}
				aria-valuenow={currentValue}
				aria-valuetext={valueText}
				aria-disabled={disabled || undefined}
				data-slot="tick-ruler-track"
				onPointerDown={handlePointerDown}
				onPointerMove={handlePointerMove}
				onPointerUp={handlePointerUp}
				onPointerCancel={handlePointerCancel}
				onKeyDown={handleKeyDown}
				onDoubleClick={() => {
					if (!disabled) settle(defaultIndex);
				}}
				className={cn(
					"relative cursor-grab overflow-hidden rounded-lg outline-none focus-visible:ring-3 focus-visible:ring-ring/50 group-data-disabled/ruler:pointer-events-none group-data-[state=dragging]/ruler:cursor-grabbing",
					horizontal
						? cn(
								"w-full touch-pan-y [mask-image:linear-gradient(to_right,transparent,black_18%,black_82%,transparent)]",
								sizeStyle.track,
							)
						: "h-64 w-20 touch-none [mask-image:linear-gradient(to_bottom,transparent,black_18%,black_82%,transparent)]",
				)}
			>
				<motion.div
					aria-hidden
					className={cn(
						"absolute will-change-transform",
						horizontal ? "top-2 left-0" : "top-0 left-3",
					)}
					style={horizontal ? { x: stripOffset } : { y: stripOffset }}
				>
					<TickStrip
						start={range.start}
						end={range.end}
						spacing={spacing}
						sign={sign}
						orientation={orientation}
						majorEvery={majorEvery}
						labelEvery={labelEvery}
						labelAt={labelAt}
					/>
				</motion.div>

				<span
					aria-hidden
					data-slot="tick-ruler-needle"
					className={cn(
						"pointer-events-none absolute rounded-full bg-[var(--tick-ruler-accent)] transition-[transform,box-shadow] duration-200 ease-out group-hover/ruler:scale-110 group-data-[state=dragging]/ruler:scale-115 group-data-[state=dragging]/ruler:shadow-[0_0_12px_2px_var(--tick-ruler-accent)]",
						horizontal
							? "top-1 left-1/2 h-9 w-[3px] origin-top -translate-x-1/2"
							: "top-1/2 left-1 h-[3px] w-11 origin-left -translate-y-1/2",
					)}
				/>
			</div>

			{presets?.length ? (
				<div
					data-slot="tick-ruler-presets"
					className={cn(
						"flex flex-wrap gap-2",
						horizontal ? "justify-center" : "flex-col",
					)}
				>
					{presets.map((preset) => {
						const active = valueToIndex(preset) === currentIndex;
						return (
							<button
								key={preset}
								type="button"
								disabled={disabled}
								data-active={active || undefined}
								onClick={() =>
									settle(valueToIndex(preset), {
										onLand: () => {
											if (haptics) void haptic("nudge");
										},
									})
								}
								className="h-8 cursor-pointer rounded-full border border-border bg-background px-3.5 font-medium text-muted-foreground text-sm tabular-nums shadow-xs outline-none transition-[color,background-color,border-color] hover:bg-muted hover:text-foreground focus-visible:ring-3 focus-visible:ring-ring/50 disabled:pointer-events-none data-active:border-transparent data-active:bg-foreground data-active:text-background dark:border-input dark:bg-input/30 dark:data-active:bg-foreground"
							>
								{format ? format(preset) : formatValue(preset)}
								{unit && !format ? ` ${unit}` : null}
							</button>
						);
					})}
				</div>
			) : null}
		</div>
	);
}

"use client";

import { Trash2Icon } from "lucide-react";
import {
	AnimatePresence,
	type HTMLMotionProps,
	motion,
	useReducedMotion,
	useTransform,
} from "motion/react";
import { type ReactNode, useId } from "react";
import {
	type UseHoldToConfirmOptions,
	useHoldToConfirm,
} from "@/hooks/use-hold-to-confirm";
import { cn } from "@/lib/utils";

const labelTransition = {
	type: "spring",
	duration: 0.3,
	bounce: 0,
} as const;

function HoldToConfirmCheck() {
	return (
		<svg
			viewBox="0 0 24 24"
			fill="none"
			stroke="currentColor"
			strokeWidth={2.5}
			strokeLinecap="round"
			strokeLinejoin="round"
			aria-hidden
			data-slot="confirmed-icon"
		>
			<motion.path
				d="M5 12.5l4.5 4.5L19 7.5"
				initial={{ pathLength: 0 }}
				animate={{ pathLength: 1 }}
				transition={{ duration: 0.35, delay: 0.08, ease: [0.23, 1, 0.32, 1] }}
			/>
		</svg>
	);
}

type HeldHandler =
	| "onPointerDown"
	| "onPointerUp"
	| "onPointerCancel"
	| "onLostPointerCapture"
	| "onKeyDown"
	| "onKeyUp"
	| "onBlur"
	| "onContextMenu";

export type HoldToConfirmProps = Omit<
	HTMLMotionProps<"button">,
	"children" | HeldHandler
> &
	UseHoldToConfirmOptions & {
		/** Label shown while idle and under the fill. */
		children?: ReactNode;
		/** Icon shown before the label. */
		icon?: ReactNode;
		/** Label shown after the hold completes. */
		confirmedLabel?: ReactNode;
		/** Icon shown after the hold completes. Defaults to an animated checkmark. */
		confirmedIcon?: ReactNode;
		/** Description announced to assistive technology. */
		instructions?: string;
		/** Class name for the fill layer, e.g. to change its color. */
		fillClassName?: string;
	};

export function HoldToConfirm({
	className,
	children = "Hold to delete",
	icon = <Trash2Icon data-slot="idle-icon" />,
	confirmedLabel = "Deleted",
	confirmedIcon,
	instructions = "Press and hold to confirm",
	fillClassName,
	holdDuration,
	resetDelay,
	onConfirm,
	onCancel,
	sound,
	haptics,
	disabled,
	...props
}: HoldToConfirmProps) {
	const { state, progress, fillOpacity, handlers } = useHoldToConfirm({
		holdDuration,
		resetDelay,
		onConfirm,
		onCancel,
		sound,
		haptics,
		disabled,
	});
	const shouldReduceMotion = useReducedMotion();
	const descriptionId = useId();
	const clipPath = useTransform(progress, (value) => {
		const clamped = Math.min(Math.max(value, 0), 1);
		return `inset(0 ${(1 - clamped) * 100}% 0 0)`;
	});
	const isHolding = state === "holding";
	const isConfirmed = state === "confirmed";

	return (
		<>
			<motion.button
				type="button"
				data-slot="hold-to-confirm"
				data-state={state}
				disabled={disabled}
				aria-describedby={descriptionId}
				aria-disabled={isConfirmed || undefined}
				animate={{ scale: isHolding && !shouldReduceMotion ? 0.97 : 1 }}
				transition={{
					type: "spring",
					visualDuration: isHolding ? 0.2 : 0.4,
					bounce: isHolding ? 0 : 0.45,
				}}
				className={cn(
					"relative inline-flex h-10 shrink-0 cursor-pointer touch-manipulation select-none items-center justify-center whitespace-nowrap rounded-full border border-border bg-background px-5 font-medium text-foreground text-sm shadow-xs outline-none transition-[background-color,box-shadow] [-webkit-touch-callout:none] hover:bg-muted focus-visible:ring-3 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 dark:border-input dark:bg-input/30 dark:hover:bg-input/50 [&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none [&_svg]:shrink-0",
					className,
				)}
				{...handlers}
				{...props}
			>
				<span className="inline-flex items-center gap-2">
					{icon}
					{children}
				</span>

				<motion.span
					aria-hidden
					data-slot="hold-to-confirm-fill"
					style={{ clipPath, opacity: fillOpacity }}
					className={cn(
						"pointer-events-none absolute -inset-px flex items-center justify-center rounded-[inherit] border border-transparent bg-destructive px-5 text-white dark:bg-red-600",
						fillClassName,
					)}
				>
					<AnimatePresence mode="popLayout" initial={false}>
						<motion.span
							key={isConfirmed ? "confirmed" : "idle"}
							initial={{ opacity: 0, scale: 0.9, filter: "blur(4px)" }}
							animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
							exit={{ opacity: 0, scale: 0.9, filter: "blur(4px)" }}
							transition={labelTransition}
							className="inline-flex items-center gap-2"
						>
							{isConfirmed ? (confirmedIcon ?? <HoldToConfirmCheck />) : icon}
							{isConfirmed ? confirmedLabel : children}
						</motion.span>
					</AnimatePresence>
				</motion.span>
			</motion.button>

			<span id={descriptionId} className="sr-only">
				{instructions}
			</span>
			<span aria-live="polite" className="sr-only">
				{isConfirmed ? confirmedLabel : null}
			</span>
		</>
	);
}

"use client";

import {
	type AnimationPlaybackControls,
	animate,
	useMotionValue,
	useMotionValueEvent,
	useReducedMotion,
} from "motion/react";
import type { KeyboardEvent, PointerEvent } from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import { useWebHaptics } from "web-haptics/react";

export type HoldState = "idle" | "holding" | "confirmed";

export type UseHoldToConfirmOptions = {
	/** How long the button must be held before confirming, in milliseconds. */
	holdDuration?: number;
	/** Delay before returning to idle after confirming. Pass `false` to stay confirmed. */
	resetDelay?: number | false;
	/** Called once the hold completes. */
	onConfirm?: () => void;
	/** Called with the reached progress (0-1) when the hold is released early. */
	onCancel?: (progress: number) => void;
	/** Play a rising tone while holding and a chime on confirm. */
	sound?: boolean;
	/** Tick haptics while holding and a success pattern on confirm. */
	haptics?: boolean;
	/** Ignore all hold input. */
	disabled?: boolean;
};

const TICK_COUNT = 10;
// The riser climbs two octaves from G3 to G5, then resolves up to a C6 chime.
const MIN_FREQUENCY = 196;
const MAX_FREQUENCY = 784;
const CHIME_FREQUENCIES = [1046.5, 1568];

let audioContext: AudioContext | null = null;

function getAudioContext() {
	if (typeof window === "undefined" || !("AudioContext" in window)) {
		return null;
	}

	audioContext ??= new AudioContext();
	if (audioContext.state === "suspended") void audioContext.resume();
	return audioContext;
}

function frequencyAt(progress: number) {
	return MIN_FREQUENCY * (MAX_FREQUENCY / MIN_FREQUENCY) ** progress;
}

function holdParam(param: AudioParam, time: number) {
	if (typeof param.cancelAndHoldAtTime === "function") {
		param.cancelAndHoldAtTime(time);
		return;
	}

	const value = param.value;
	param.cancelScheduledValues(time);
	param.setValueAtTime(value, time);
}

type Riser = {
	release: () => void;
	finish: () => void;
};

function startRiser(progress: number, remaining: number): Riser | null {
	const ctx = getAudioContext();
	if (!ctx) return null;

	const now = ctx.currentTime;
	const oscillator = ctx.createOscillator();
	const filter = ctx.createBiquadFilter();
	const gain = ctx.createGain();

	oscillator.type = "triangle";
	oscillator.frequency.setValueAtTime(frequencyAt(progress), now);
	oscillator.frequency.exponentialRampToValueAtTime(
		MAX_FREQUENCY,
		now + Math.max(remaining, 0.01),
	);

	filter.type = "lowpass";
	filter.frequency.value = 2400;

	gain.gain.setValueAtTime(0, now);
	gain.gain.linearRampToValueAtTime(0.05, now + 0.05);

	oscillator.connect(filter).connect(gain).connect(ctx.destination);
	oscillator.start(now);

	let stopped = false;
	const stop = (fade: number, drop: boolean) => {
		if (stopped) return;
		stopped = true;

		const time = ctx.currentTime;
		holdParam(oscillator.frequency, time);
		holdParam(gain.gain, time);
		if (drop) {
			oscillator.frequency.exponentialRampToValueAtTime(
				MIN_FREQUENCY,
				time + fade,
			);
		}
		gain.gain.linearRampToValueAtTime(0, time + fade);
		oscillator.stop(time + fade + 0.02);
	};

	return {
		release: () => stop(0.18, true),
		finish: () => stop(0.04, false),
	};
}

function playChime() {
	const ctx = getAudioContext();
	if (!ctx) return;

	const now = ctx.currentTime;
	CHIME_FREQUENCIES.forEach((frequency, index) => {
		const start = now + index * 0.08;
		const oscillator = ctx.createOscillator();
		const gain = ctx.createGain();

		oscillator.type = "sine";
		oscillator.frequency.value = frequency;
		gain.gain.setValueAtTime(0, start);
		gain.gain.linearRampToValueAtTime(0.08, start + 0.005);
		gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.6);

		oscillator.connect(gain).connect(ctx.destination);
		oscillator.start(start);
		oscillator.stop(start + 0.65);
	});
}

function isHoldKey(key: string) {
	return key === " " || key === "Enter";
}

export function useHoldToConfirm({
	holdDuration = 1500,
	resetDelay = 2000,
	onConfirm,
	onCancel,
	sound = true,
	haptics = true,
	disabled = false,
}: UseHoldToConfirmOptions = {}) {
	const [state, setState] = useState<HoldState>("idle");
	const stateRef = useRef<HoldState>("idle");
	const progress = useMotionValue(0);
	const fillOpacity = useMotionValue(1);
	const animationRef = useRef<AnimationPlaybackControls | null>(null);
	const riserRef = useRef<Riser | null>(null);
	const resetTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
	const lastTickRef = useRef(0);
	const callbacksRef = useRef({ onConfirm, onCancel });
	const { trigger: haptic } = useWebHaptics();

	// Sound follows the same reduced-motion opt-out as the other TentUI sounds.
	const shouldReduceMotion = useReducedMotion();
	const soundEnabled = sound && !shouldReduceMotion;

	useEffect(() => {
		callbacksRef.current = { onConfirm, onCancel };
	}, [onConfirm, onCancel]);

	const updateState = useCallback((next: HoldState) => {
		stateRef.current = next;
		setState(next);
	}, []);

	const clearResetTimeout = useCallback(() => {
		if (resetTimeoutRef.current) {
			clearTimeout(resetTimeoutRef.current);
			resetTimeoutRef.current = null;
		}
	}, []);

	const reset = useCallback(() => {
		clearResetTimeout();
		animationRef.current?.stop();

		if (stateRef.current !== "confirmed") {
			progress.set(0);
			updateState("idle");
			return;
		}

		animationRef.current = animate(fillOpacity, 0, {
			duration: 0.2,
			ease: [0.23, 1, 0.32, 1],
			onComplete: () => {
				progress.set(0);
				fillOpacity.set(1);
				updateState("idle");
			},
		});
	}, [clearResetTimeout, fillOpacity, progress, updateState]);

	const confirm = useCallback(() => {
		updateState("confirmed");
		progress.set(1);

		riserRef.current?.finish();
		riserRef.current = null;
		if (soundEnabled) playChime();
		if (haptics) void haptic("success");

		callbacksRef.current.onConfirm?.();

		if (resetDelay !== false) {
			resetTimeoutRef.current = setTimeout(reset, resetDelay);
		}
	}, [haptic, haptics, progress, reset, resetDelay, soundEnabled, updateState]);

	const start = useCallback(() => {
		if (disabled || stateRef.current !== "idle") return;

		updateState("holding");
		const from = Math.min(Math.max(progress.get(), 0), 1);
		const remaining = (holdDuration / 1000) * (1 - from);
		lastTickRef.current = Math.floor(from * TICK_COUNT);

		animationRef.current?.stop();
		animationRef.current = animate(progress, 1, {
			duration: remaining,
			ease: "linear",
			onComplete: confirm,
		});

		if (soundEnabled) riserRef.current = startRiser(from, remaining);
		if (haptics) void haptic([{ duration: 10, intensity: 0.4 }]);
	}, [
		confirm,
		disabled,
		haptic,
		haptics,
		holdDuration,
		progress,
		soundEnabled,
		updateState,
	]);

	const cancel = useCallback(() => {
		if (stateRef.current !== "holding") return;

		updateState("idle");
		const reached = progress.get();

		animationRef.current?.stop();
		animationRef.current = animate(
			progress,
			0,
			shouldReduceMotion
				? { duration: 0.2, ease: [0.23, 1, 0.32, 1] }
				: { type: "spring", visualDuration: 0.35, bounce: 0.2 },
		);

		riserRef.current?.release();
		riserRef.current = null;

		callbacksRef.current.onCancel?.(reached);
	}, [progress, shouldReduceMotion, updateState]);

	// Tick a little harder at each step so the phone feels the hold building.
	useMotionValueEvent(progress, "change", (value) => {
		if (!haptics || stateRef.current !== "holding") return;

		const tick = Math.floor(value * TICK_COUNT);
		if (tick > lastTickRef.current && tick < TICK_COUNT) {
			lastTickRef.current = tick;
			void haptic([{ duration: 8, intensity: 0.3 + 0.6 * value }]);
		}
	});

	useEffect(() => {
		if (disabled) cancel();
	}, [disabled, cancel]);

	useEffect(() => {
		return () => {
			clearResetTimeout();
			animationRef.current?.stop();
			riserRef.current?.finish();
		};
	}, [clearResetTimeout]);

	const handlers = {
		onPointerDown: (event: PointerEvent<HTMLElement>) => {
			if (event.button !== 0) return;
			event.currentTarget.setPointerCapture(event.pointerId);
			start();
		},
		onPointerUp: cancel,
		onPointerCancel: cancel,
		onLostPointerCapture: cancel,
		onKeyDown: (event: KeyboardEvent<HTMLElement>) => {
			if (!isHoldKey(event.key)) return;
			event.preventDefault();
			if (!event.repeat) start();
		},
		onKeyUp: (event: KeyboardEvent<HTMLElement>) => {
			if (isHoldKey(event.key)) cancel();
		},
		onBlur: cancel,
		onContextMenu: (event: { preventDefault: () => void }) => {
			event.preventDefault();
		},
	};

	return { state, progress, fillOpacity, handlers, reset } as const;
}

"use client";

import type { CSSProperties } from "react";
import { useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

type SpriteFrame = {
	column: number;
	row: number;
};

type Direction =
	| "center"
	| "east"
	| "north"
	| "north-east"
	| "north-west"
	| "south"
	| "south-east"
	| "south-west"
	| "west";

export type DirectionFrameMap = Record<Direction, SpriteFrame>;

export type InteractiveSpriteProps = {
	/** Accessible description for the character. Use an empty string when decorative. */
	alt: string;
	/** Number of equally sized columns in the sprite sheet. */
	columns?: number;
	/** Distance from the character's center that keeps the resting frame active. */
	deadZone?: number;
	/** Maps pointer directions to cells in the sprite sheet. */
	frames?: DirectionFrameMap;
	/** Time without pointer movement before returning to the center frame. */
	idleDelay?: number;
	/** Number of equally sized rows in the sprite sheet. */
	rows?: number;
	/** Public URL for the sprite sheet. */
	src: string;
	className?: string;
	style?: CSSProperties;
};

const DEFAULT_FRAMES: DirectionFrameMap = {
	"north-west": { column: 0, row: 0 },
	north: { column: 1, row: 0 },
	"north-east": { column: 2, row: 0 },
	west: { column: 0, row: 1 },
	center: { column: 1, row: 1 },
	east: { column: 2, row: 1 },
	"south-west": { column: 0, row: 2 },
	south: { column: 1, row: 2 },
	"south-east": { column: 2, row: 2 },
};

const OCTANTS: Direction[] = [
	"east",
	"south-east",
	"south",
	"south-west",
	"west",
	"north-west",
	"north",
	"north-east",
];

function getDirection(deltaX: number, deltaY: number, deadZone: number) {
	if (Math.hypot(deltaX, deltaY) <= deadZone) return "center";

	const octant =
		(Math.round(Math.atan2(deltaY, deltaX) / (Math.PI / 4)) + 8) % 8;

	return OCTANTS[octant];
}

function getBackgroundPosition(
	frame: SpriteFrame,
	columns: number,
	rows: number,
) {
	const x = columns === 1 ? 0 : (frame.column / (columns - 1)) * 100;
	const y = rows === 1 ? 0 : (frame.row / (rows - 1)) * 100;

	return `${x}% ${y}%`;
}

export function InteractiveSprite({
	alt,
	className,
	columns = 3,
	deadZone = 24,
	frames = DEFAULT_FRAMES,
	idleDelay = 300,
	rows = 3,
	src,
	style,
}: InteractiveSpriteProps) {
	const rootRef = useRef<HTMLSpanElement>(null);
	const activeDirectionRef = useRef<Direction>("center");
	const [activeDirection, setActiveDirection] = useState<Direction>("center");

	useEffect(() => {
		const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
		let animationFrame: number | null = null;
		let idleTimeout: number | undefined;

		const resetDirection = () => {
			if (activeDirectionRef.current === "center") return;

			activeDirectionRef.current = "center";
			setActiveDirection("center");
		};

		const handlePointerMove = (event: PointerEvent) => {
			if (event.pointerType === "touch" || reducedMotion.matches) return;

			window.clearTimeout(idleTimeout);
			if (animationFrame !== null) cancelAnimationFrame(animationFrame);

			animationFrame = requestAnimationFrame(() => {
				animationFrame = null;
				const root = rootRef.current;
				if (!root || reducedMotion.matches) return;

				const bounds = root.getBoundingClientRect();
				const direction = getDirection(
					event.clientX - (bounds.left + bounds.width / 2),
					event.clientY - (bounds.top + bounds.height / 2),
					deadZone,
				);

				if (direction !== activeDirectionRef.current) {
					activeDirectionRef.current = direction;
					setActiveDirection(direction);
				}

				idleTimeout = window.setTimeout(resetDirection, idleDelay);
			});
		};

		const handleMotionPreferenceChange = () => {
			if (reducedMotion.matches) resetDirection();
		};

		window.addEventListener("pointermove", handlePointerMove, {
			passive: true,
		});
		reducedMotion.addEventListener("change", handleMotionPreferenceChange);

		return () => {
			window.removeEventListener("pointermove", handlePointerMove);
			reducedMotion.removeEventListener("change", handleMotionPreferenceChange);
			window.clearTimeout(idleTimeout);
			if (animationFrame !== null) cancelAnimationFrame(animationFrame);
		};
	}, [deadZone, idleDelay]);

	const frame = frames[activeDirection];
	const spriteStyle: CSSProperties = {
		backgroundImage: `url("${src}")`,
		backgroundPosition: getBackgroundPosition(frame, columns, rows),
		backgroundRepeat: "no-repeat",
		backgroundSize: `${columns * 100}% ${rows * 100}%`,
	};
	const accessibilityProps = alt
		? { "aria-label": alt, role: "img" }
		: { "aria-hidden": true as const };

	return (
		<span
			ref={rootRef}
			className={cn("block overflow-hidden", className)}
			data-direction={activeDirection}
			data-slot="interactive-sprite"
			style={style}
			{...accessibilityProps}
		>
			<span
				aria-hidden="true"
				className="block size-full"
				style={spriteStyle}
			/>
		</span>
	);
}

"use client";

import type { ComponentProps } from "react";
import { useEffect, useRef } from "react";

import { cn } from "@/lib/utils";

const TAU = Math.PI * 2;
const MAX_SIZE = 0.9;
const SPEED = 0.02;
const ALPHA_STEPS = 6;

const clamp = (value: number, min: number, max: number) =>
	Math.min(max, Math.max(min, value));

function smoothstep(value: number, edge0: number, edge1: number) {
	const t = clamp((value - edge0) / (edge1 - edge0), 0, 1);
	return t * t * (3 - 2 * t);
}

function hash(x: number, y: number) {
	const value = Math.sin(x * 127.1 + y * 311.7) * 43758.5453;
	return value - Math.floor(value);
}

class TileFieldEngine {
	private canvas: HTMLCanvasElement;
	private ctx: CanvasRenderingContext2D;
	private host: HTMLElement;
	private color: string;
	private reducedMotion: boolean;
	private restColor = "gray";
	private word: string;

	private dpr = Math.min(2, window.devicePixelRatio || 1);
	private viewW = 0;
	private viewH = 0;
	private cell = 10;
	private time = 0;

	private n = 0;
	private px = new Float32Array(0);
	private py = new Float32Array(0);
	private drawX = new Float32Array(0);
	private drawY = new Float32Array(0);
	private spark = new Uint8Array(0);
	private lit = new Float32Array(0);
	private seed = new Float32Array(0);

	private hasPointer = false;
	private rawX = 0;
	private rawY = 0;
	private lightX = 0;
	private lightY = 0;
	private lightSpeed = 0;
	private raf = 0;

	constructor(host: HTMLElement, word: string, color: string) {
		this.host = host;
		this.word = word;
		this.color = color;
		this.canvas = document.createElement("canvas");
		this.canvas.className =
			"pointer-events-none absolute inset-0 block size-full";
		this.canvas.setAttribute("aria-hidden", "true");
		this.ctx = this.canvas.getContext("2d")!;
		this.host.appendChild(this.canvas);
		this.reducedMotion = window.matchMedia(
			"(prefers-reduced-motion: reduce)",
		).matches;

		this.resize();
		this.host.addEventListener("pointermove", this.onMove, { passive: true });
		this.host.addEventListener("pointerleave", this.onLeave);
	}

	resize() {
		const rect = this.host.getBoundingClientRect();
		this.viewW = rect.width;
		this.viewH = rect.height;
		this.dpr = Math.min(2, window.devicePixelRatio || 1);
		this.cell = Math.max(2, Math.round(this.viewW / 460));

		this.canvas.style.width = `${Math.round(this.viewW)}px`;
		this.canvas.style.height = `${Math.round(this.viewH)}px`;
		this.canvas.width = Math.ceil(this.viewW * this.dpr);
		this.canvas.height = Math.ceil(this.viewH * this.dpr);
		this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
		this.ctx.imageSmoothingEnabled = false;
		this.updateTheme();

		const source = document.createElement("canvas");
		source.width = Math.max(1, Math.floor(this.viewW));
		source.height = Math.max(1, Math.floor(this.viewH));
		const sourceCtx = source.getContext("2d")!;
		const spacedCtx = sourceCtx as CanvasRenderingContext2D & {
			letterSpacing?: string;
		};
		sourceCtx.fillStyle = "#000";
		sourceCtx.textAlign = "center";
		sourceCtx.textBaseline = "middle";

		let fontSize = this.viewH * 0.9;
		spacedCtx.letterSpacing = `${-0.02 * fontSize}px`;
		sourceCtx.font = `600 ${fontSize}px ui-sans-serif, system-ui, Arial, sans-serif`;
		const measuredWidth = sourceCtx.measureText(this.word).width || 1;
		fontSize *= (this.viewW * 0.92) / measuredWidth;
		spacedCtx.letterSpacing = `${-0.02 * fontSize}px`;
		sourceCtx.font = `600 ${fontSize}px ui-sans-serif, system-ui, Arial, sans-serif`;
		sourceCtx.fillText(this.word, this.viewW / 2, this.viewH / 2);

		const data = sourceCtx.getImageData(0, 0, source.width, source.height).data;
		const xs: number[] = [];
		const ys: number[] = [];
		const sparks: number[] = [];
		const seeds: number[] = [];
		const columns = Math.ceil(this.viewW / this.cell);
		const rows = Math.ceil(this.viewH / this.cell);

		for (let row = 0; row < rows; row++) {
			for (let column = 0; column < columns; column++) {
				const x = Math.floor(column * this.cell + this.cell / 2);
				const y = Math.floor(row * this.cell + this.cell / 2);
				if (x >= source.width || y >= source.height) continue;

				const alpha = (data[(y * source.width + x) * 4 + 3] ?? 0) / 255;
				if (alpha <= 0.5) continue;

				xs.push(x);
				ys.push(y);
				sparks.push(hash(x + 7, y - 3) > 0.82 ? 1 : 0);
				seeds.push(hash(x * 1.3, y * 0.7));
			}
		}

		this.n = xs.length;
		this.px = new Float32Array(xs);
		this.py = new Float32Array(ys);
		this.drawX = new Float32Array(xs);
		this.drawY = new Float32Array(ys);
		this.spark = new Uint8Array(sparks);
		this.seed = new Float32Array(seeds);
		this.lit = new Float32Array(this.n);

		if (this.reducedMotion) this.renderStatic();
	}

	private distSegSq(
		qx: number,
		qy: number,
		ax: number,
		ay: number,
		bx: number,
		by: number,
	) {
		const dx = bx - ax;
		const dy = by - ay;
		if (dx === 0 && dy === 0) {
			const ex = qx - ax;
			const ey = qy - ay;
			return ex * ex + ey * ey;
		}

		const t = clamp(
			((qx - ax) * dx + (qy - ay) * dy) / (dx * dx + dy * dy),
			0,
			1,
		);
		const ex = qx - (ax + dx * t);
		const ey = qy - (ay + dy * t);
		return ex * ex + ey * ey;
	}

	private frame = (timestamp: number) => {
		const { viewW, viewH, cell, n, px, py } = this;
		const drawX = this.drawX;
		const drawY = this.drawY;
		const spark = this.spark;
		const lit = this.lit;
		const seed = this.seed;
		this.ctx.clearRect(0, 0, viewW, viewH);
		this.time += SPEED;
		const time = this.time;

		const previousX = this.lightX;
		const previousY = this.lightY;
		if (this.hasPointer) {
			this.lightX += (this.rawX - this.lightX) * 0.5;
			this.lightY += (this.rawY - this.lightY) * 0.5;
		}

		const lightX = this.lightX;
		const lightY = this.lightY;
		const stepDistance = Math.hypot(lightX - previousX, lightY - previousY);
		this.lightSpeed = 0.9 * this.lightSpeed + 0.1 * stepDistance;

		const reach = clamp(
			viewH * 0.22 + this.lightSpeed * 0.9,
			viewH * 0.18,
			viewH * 0.42,
		);
		const influence = 1.5 * reach;
		const influenceSq = influence * influence;
		const minX = Math.min(previousX, lightX) - influence;
		const maxX = Math.max(previousX, lightX) + influence;
		const minY = Math.min(previousY, lightY) - influence;
		const maxY = Math.max(previousY, lightY) + influence;

		const grayPath = new Path2D();
		const litList: number[] = [];
		const buckets = Array.from({ length: ALPHA_STEPS }, () => new Path2D());

		for (let index = 0; index < n; index++) {
			const x = px[index];
			const y = py[index];
			let target = 0;

			if (this.hasPointer && x >= minX && x <= maxX && y >= minY && y <= maxY) {
				const distanceSq = this.distSegSq(
					x,
					y,
					previousX,
					previousY,
					lightX,
					lightY,
				);
				if (distanceSq <= influenceSq) {
					const angle = Math.atan2(y - lightY, x - lightX);
					const wobble =
						1 +
						0.3 * Math.sin(3 * angle + time * 1.6) +
						0.16 * Math.sin(5 * angle - time * 1.1 + 1.3);
					const amount = clamp(
						1 - Math.sqrt(distanceSq) / (reach * wobble),
						0,
						1,
					);
					target = amount * amount * (3 - 2 * amount);
				}
			}

			const rate = target > lit[index] ? 0.24 : 0.02;
			lit[index] += (target - lit[index]) * rate;

			const pointerX = x - lightX;
			const pointerY = y - lightY;
			const pointerDistance = Math.max(1, Math.hypot(pointerX, pointerY));
			const motion =
				lit[index] *
				cell *
				(0.65 + 0.2 * Math.sin(seed[index] * TAU + time * 2));
			const drift = lit[index] * cell * 0.18;
			const tileX =
				x +
				(pointerX / pointerDistance) * motion +
				Math.sin(seed[index] * TAU + time * 2.4) * drift;
			const tileY =
				y +
				(pointerY / pointerDistance) * motion +
				Math.cos(seed[index] * TAU - time * 2) * drift;
			drawX[index] = tileX;
			drawY[index] = tileY;

			const u = x / Math.max(viewW, 1);
			const v = y / Math.max(viewH, 1);
			const flow =
				Math.sin((u * 1.6 + 0.4 * Math.sin(time * 0.3)) * TAU + time * 0.8) +
				0.7 * Math.sin((v * 2.1 - u * 0.9) * TAU - time * 0.6 + 1.7) +
				0.5 * Math.sin((u * 3.3 + v * 2.7) * TAU + time * 0.4 + 4.2) +
				0.4 *
					Math.cos((v * 1.3 - 1.1 * Math.sin(time * 0.2)) * TAU - time * 0.5);
			let colorAmount = smoothstep(flow, 0.1, 1.6);
			colorAmount = Math.max(colorAmount, lit[index]);

			const breathe = 0.5 + 0.5 * Math.sin(seed[index] * TAU + time * 1.3);
			const base = 0.42 + 0.08 * breathe;
			const size = cell * (base + (MAX_SIZE - base) * colorAmount);
			const half = size / 2;
			grayPath.rect(tileX - half, tileY - half, size, size);

			if (colorAmount > 0.04) {
				const alphaStep = Math.min(
					ALPHA_STEPS - 1,
					Math.floor(colorAmount * ALPHA_STEPS),
				);
				buckets[alphaStep].rect(tileX - half, tileY - half, size, size);
			}

			if (lit[index] > 0.02) litList.push(index);
		}

		this.ctx.fillStyle = this.restColor;
		this.ctx.fill(grayPath);

		this.ctx.fillStyle = this.color;
		for (let alphaStep = 0; alphaStep < ALPHA_STEPS; alphaStep++) {
			this.ctx.globalAlpha = (alphaStep + 1) / ALPHA_STEPS;
			this.ctx.fill(buckets[alphaStep]);
		}
		this.ctx.globalAlpha = 1;

		for (const index of litList) {
			const light = lit[index];
			const x = drawX[index];
			const y = drawY[index];
			const glowSize = cell * (0.7 + (MAX_SIZE - 0.7) * light);
			const glowHalf = glowSize / 2;

			if (spark[index]) {
				const phase = seed[index];
				const sparkTime = 0.00025 * timestamp;
				const amplitude = (0.45 + phase) * cell * 0.28;
				const jitterX =
					x + Math.sin(0.05 * x + 1.3 * sparkTime + phase * TAU) * amplitude;
				const jitterY =
					y + Math.cos(0.04 * y - 0.9 * sparkTime + phase * TAU) * amplitude;
				this.ctx.globalAlpha = 0.1 * light;
				this.ctx.fillStyle = this.color;
				this.ctx.fillRect(
					jitterX - glowHalf * 1.5,
					jitterY - glowHalf * 1.5,
					glowSize * 1.5,
					glowSize * 1.5,
				);
				this.ctx.globalAlpha = 0.55 * light;
				this.ctx.fillRect(
					jitterX - glowHalf,
					jitterY - glowHalf,
					glowSize,
					glowSize,
				);
			} else {
				this.ctx.globalAlpha = 0.85 * light;
				this.ctx.fillStyle = this.color;
				this.ctx.fillRect(x - glowHalf, y - glowHalf, glowSize, glowSize);
			}
		}
		this.ctx.globalAlpha = 1;

		this.raf = requestAnimationFrame(this.frame);
	};

	renderStatic() {
		this.ctx.clearRect(0, 0, this.viewW, this.viewH);
		const path = new Path2D();
		for (let index = 0; index < this.n; index++) {
			const size = this.cell * 0.5;
			const half = size / 2;
			path.rect(this.px[index] - half, this.py[index] - half, size, size);
		}
		this.ctx.fillStyle = this.restColor;
		this.ctx.fill(path);
	}

	updateTheme() {
		this.restColor = getComputedStyle(this.host).color;
		if (this.reducedMotion) this.renderStatic();
	}

	setColor(color: string) {
		this.color = color;
	}

	setReducedMotion(reducedMotion: boolean) {
		this.reducedMotion = reducedMotion;
		if (reducedMotion) this.renderStatic();
	}

	private onMove = (event: PointerEvent) => {
		if (event.pointerType === "touch") return;

		const rect = this.host.getBoundingClientRect();
		const x = event.clientX - rect.left;
		const y = event.clientY - rect.top;
		if (!this.hasPointer) {
			this.hasPointer = true;
			this.lightX = x;
			this.lightY = y;
			this.lightSpeed = 0;
		}
		this.rawX = x;
		this.rawY = y;
	};

	private onLeave = () => {
		this.hasPointer = false;
	};

	start() {
		if (this.reducedMotion || this.raf) return;
		this.raf = requestAnimationFrame(this.frame);
	}

	stop() {
		if (this.raf) cancelAnimationFrame(this.raf);
		this.raf = 0;
	}

	destroy() {
		this.stop();
		this.host.removeEventListener("pointermove", this.onMove);
		this.host.removeEventListener("pointerleave", this.onLeave);
		this.canvas.remove();
	}
}

export interface TileFieldProps
	extends Omit<ComponentProps<"div">, "children" | "ref"> {
	/** Color used by the wave, pointer glow, and sparks. */
	color?: string;
	/** Text rendered into the tile grid. */
	word?: string;
}

export function TileField({
	"aria-label": ariaLabel,
	className,
	color = "#6366f1",
	word = "Localhost",
	...props
}: TileFieldProps) {
	const hostRef = useRef<HTMLDivElement>(null);
	const engineRef = useRef<TileFieldEngine>(null);
	const colorRef = useRef(color);
	colorRef.current = color;

	useEffect(() => {
		const host = hostRef.current;
		if (!host) return;

		const engine = new TileFieldEngine(host, word, colorRef.current);
		engineRef.current = engine;
		const motionQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
		let isInView = true;

		const syncAnimation = () => {
			engine.setReducedMotion(motionQuery.matches);
			if (isInView && !document.hidden && !motionQuery.matches) {
				engine.start();
			} else {
				engine.stop();
			}
		};
		const resizeObserver = new ResizeObserver(() => engine.resize());
		const themeObserver = new MutationObserver(() => engine.updateTheme());
		const intersectionObserver = new IntersectionObserver(([entry]) => {
			isInView = entry?.isIntersecting ?? true;
			syncAnimation();
		});

		resizeObserver.observe(host);
		themeObserver.observe(document.documentElement, {
			attributeFilter: ["class", "style"],
			attributes: true,
		});
		intersectionObserver.observe(host);
		document.addEventListener("visibilitychange", syncAnimation);
		motionQuery.addEventListener("change", syncAnimation);
		syncAnimation();

		return () => {
			resizeObserver.disconnect();
			themeObserver.disconnect();
			intersectionObserver.disconnect();
			document.removeEventListener("visibilitychange", syncAnimation);
			motionQuery.removeEventListener("change", syncAnimation);
			engine.destroy();
			engineRef.current = null;
		};
	}, [word]);

	useEffect(() => engineRef.current?.setColor(color), [color]);

	return (
		<div
			aria-label={ariaLabel ?? word}
			className={cn(
				"relative isolate min-h-48 w-full overflow-hidden text-muted-foreground",
				className,
			)}
			data-slot="tile-field"
			ref={hostRef}
			role="img"
			{...props}
		/>
	);
}

"use client";

import { CopyIcon, CornerDownLeftIcon, SearchIcon } from "lucide-react";
import * as React from "react";
import { useHotkeys } from "react-hotkeys-hook";

import { Button } from "@/components/ui/button";
import {
	CommandDialog,
	CommandEmpty,
	CommandGroup,
	CommandInput,
	CommandItem,
	CommandList,
	CommandShortcut,
} from "@/components/ui/command";
import { Kbd, KbdGroup } from "@/components/ui/kbd";
import { cn } from "@/lib/utils";

export type SearchCommandItem = {
	/** Stable identity when items may be reordered. */
	id?: string;
	/** Primary searchable label. */
	title: string;
	/** Optional text included in search without being displayed. */
	description?: string;
	/** Overrides the value used by the command menu's filter. */
	value?: string;
	/** Additional terms that should match this item. */
	keywords?: readonly string[];
	icon?: React.ReactNode;
	/** Supporting metadata displayed at the end of the row. */
	meta?: React.ReactNode;
	/** Compact keyboard sequence displayed at the end of the row. */
	shortcut?: string;
	/** Overrides the footer action while this item is highlighted. */
	actionLabel?: string;
	disabled?: boolean;
	/** Runs immediately before the menu closes. */
	onBeforeSelect?: () => void;
	onSelect?: () => void;
};

export type SearchCommandGroup = {
	heading: string;
	items: readonly SearchCommandItem[];
	/** Footer action used by items in this group. */
	actionLabel?: string;
};

export type SearchCommandProps = {
	groups: readonly SearchCommandGroup[];
	/** Controlled dialog state. */
	open?: boolean;
	/** Initial dialog state when uncontrolled. */
	defaultOpen?: boolean;
	onOpenChange?: (open: boolean) => void;
	onItemSelect?: (item: SearchCommandItem) => void;
	/** Enables the configured modifier shortcut and slash. */
	enabledHotkeys?: boolean;
	/** Character used with Command or Control to open the menu. */
	shortcutKey?: string;
	/** Overrides the modifier displayed in the trigger. */
	shortcutModifier?: "auto" | "command" | "control";
	triggerLabel?: string;
	triggerSlot?: string;
	placeholder?: string;
	emptyMessage?: React.ReactNode;
	title?: string;
	description?: string;
	footerIcon?: React.ReactNode;
	defaultActionLabel?: string;
	triggerClassName?: string;
	dialogClassName?: string;
	listClassName?: string;
};

export function SearchCommand({
	defaultActionLabel = "Open",
	defaultOpen = false,
	description = "Search for a command to run...",
	dialogClassName,
	emptyMessage = "No results found.",
	enabledHotkeys = false,
	footerIcon,
	groups,
	listClassName,
	onItemSelect,
	onOpenChange,
	open,
	placeholder = "Type a command or search…",
	shortcutKey = "k",
	shortcutModifier = "auto",
	title = "Command Palette",
	triggerClassName,
	triggerLabel = "Search…",
	triggerSlot = "command-menu-trigger",
}: SearchCommandProps) {
	const [internalOpen, setInternalOpen] = React.useState(defaultOpen);
	const [selectedActionLabel, setSelectedActionLabel] =
		React.useState(defaultActionLabel);
	const isOpen = open ?? internalOpen;
	const normalizedShortcutKey = shortcutKey.trim().toLowerCase();
	const displayedShortcutKey = normalizedShortcutKey.toUpperCase();
	const ariaKeyShortcuts =
		shortcutModifier === "command"
			? `Meta+${displayedShortcutKey} /`
			: shortcutModifier === "control"
				? `Control+${displayedShortcutKey} /`
				: `Meta+${displayedShortcutKey} Control+${displayedShortcutKey} /`;

	const setOpen = React.useCallback(
		(nextOpen: boolean) => {
			if (open === undefined) setInternalOpen(nextOpen);
			onOpenChange?.(nextOpen);
		},
		[onOpenChange, open],
	);

	useHotkeys(
		`mod+${normalizedShortcutKey}, slash`,
		(event) => {
			event.preventDefault();
			setOpen(!isOpen);
		},
		{ enabled: enabledHotkeys },
	);

	function handleItemSelect(item: SearchCommandItem) {
		item.onBeforeSelect?.();
		setOpen(false);
		item.onSelect?.();
		onItemSelect?.(item);
	}

	return (
		<>
			<Button
				aria-expanded={isOpen}
				aria-haspopup="dialog"
				aria-keyshortcuts={ariaKeyShortcuts}
				aria-label={triggerLabel}
				className={cn(
					"select-none gap-1.5 border-none px-1.5 text-muted-foreground will-change-[scale]",
					triggerClassName,
				)}
				data-slot={triggerSlot}
				onClick={() => setOpen(true)}
				size="sm"
				variant="ghost"
			>
				<SearchIcon />
				<span className="font-medium font-sans text-sm/4 sm:hidden">
					{triggerLabel}
				</span>
				{shortcutModifier !== "control" ? (
					<KbdGroup
						className={cn(
							"hidden gap-0.75",
							shortcutModifier === "command"
								? "sm:flex"
								: "sm:in-[.os-macos_&]:flex",
						)}
					>
						<Kbd className="w-5 min-w-auto">⌘</Kbd>
						<Kbd className="w-5 min-w-auto">{displayedShortcutKey}</Kbd>
					</KbdGroup>
				) : null}
				{shortcutModifier !== "command" ? (
					<KbdGroup
						className={cn(
							"hidden gap-0.75",
							shortcutModifier === "control"
								? "sm:flex"
								: "sm:not-[.os-macos_&]:flex",
						)}
					>
						<Kbd>Ctrl</Kbd>
						<Kbd className="w-5 min-w-auto">{displayedShortcutKey}</Kbd>
					</KbdGroup>
				) : null}
			</Button>

			<CommandDialog
				className={dialogClassName}
				description={description}
				onOpenChange={setOpen}
				open={isOpen}
				title={title}
			>
				<SearchCommandInput placeholder={placeholder} />

				<div className="rounded-xl bg-background ring-1 ring-border">
					<CommandList className={cn("scroll-fade min-h-80", listClassName)}>
						<CommandEmpty>{emptyMessage}</CommandEmpty>
						{groups.map((group) => (
							<CommandGroup heading={group.heading} key={group.heading}>
								{group.items.map((item, index) => {
									const actionLabel =
										item.actionLabel ?? group.actionLabel ?? defaultActionLabel;
									const keywords = [
										...(item.keywords ?? []),
										...(item.description ? [item.description] : []),
									];
									return (
										<SearchCommandMenuItem
											disabled={item.disabled}
											key={item.id ?? `${item.value ?? item.title}-${index}`}
											keywords={keywords.length > 0 ? keywords : undefined}
											onHighlight={() => setSelectedActionLabel(actionLabel)}
											onSelect={() => handleItemSelect(item)}
											value={item.value}
										>
											{item.icon ?? <CopyIcon />}
											<p className="line-clamp-1">{item.title}</p>
											{item.meta ? (
												<span className="ml-auto font-mono font-normal text-muted-foreground text-xs tabular-nums max-sm:hidden">
													{item.meta}
												</span>
											) : null}
											{item.shortcut ? (
												<CommandShortcut className="font-mono tracking-[0.2em] max-sm:hidden">
													{item.shortcut}
												</CommandShortcut>
											) : null}
										</SearchCommandMenuItem>
									);
								})}
							</CommandGroup>
						))}
					</CommandList>
				</div>

				<div className="flex h-10" />
				<div className="absolute inset-x-0 bottom-0 flex h-10 items-center justify-between gap-2 rounded-b-2xl px-4 font-medium text-xs">
					<span className="size-4 shrink-0">
						{footerIcon ?? <SearchIcon className="size-full" />}
					</span>
					<div className="flex items-center gap-2 max-sm:hidden">
