"use client";

import { useReducedMotion } from "motion/react";
import { useCallback, useEffect, useRef, useState } from "react";

import { decodeAudioData, getAudioContext } from "@/lib/soundcn/sound-engine";
import type {
	SoundAsset,
	UseSoundOptions,
	UseSoundReturn,
} from "@/lib/soundcn/sound-types";

export function useSound(
	sound: SoundAsset,
	options: UseSoundOptions = {},
): UseSoundReturn {
	const {
		volume = 0.5,
		playbackRate = 1,
		interrupt = false,
		soundEnabled: _soundEnabled = true,
		onPlay,
		onEnd,
		onPause,
		onStop,
	} = options;

	const [isPlaying, setIsPlaying] = useState(false);
	const [duration, setDuration] = useState<number | null>(
		sound.duration ?? null,
	);
	const sourceRef = useRef<AudioBufferSourceNode | null>(null);
	const gainRef = useRef<GainNode | null>(null);
	const bufferRef = useRef<AudioBuffer | null>(null);

	const shouldReduceMotion = useReducedMotion();
	const soundEnabled = _soundEnabled && !shouldReduceMotion;

	useEffect(() => {
		let cancelled = false;

		void decodeAudioData(sound.dataUri)
			.then((buffer) => {
				if (!cancelled) {
					bufferRef.current = buffer;
					setDuration(buffer.duration);
				}
			})
			.catch(() => {
				if (!cancelled) {
					bufferRef.current = null;
					setDuration(sound.duration ?? null);
				}
			});

		return () => {
			cancelled = true;
		};
	}, [sound.dataUri, sound.duration]);

	const stop = useCallback(() => {
		if (sourceRef.current) {
			try {
				sourceRef.current.stop();
			} catch {
				// Already stopped
			}
			sourceRef.current = null;
		}
		setIsPlaying(false);
		onStop?.();
	}, [onStop]);

	const play = useCallback(
		(overrides?: { volume?: number; playbackRate?: number }) => {
			if (!soundEnabled || !bufferRef.current) return;

			const ctx = getAudioContext();

			if (ctx.state === "suspended") {
				ctx.resume();
			}

			if (interrupt && sourceRef.current) {
				stop();
			}

			const source = ctx.createBufferSource();
			const gain = ctx.createGain();

			source.buffer = bufferRef.current;
			source.playbackRate.value = overrides?.playbackRate ?? playbackRate;
			gain.gain.value = overrides?.volume ?? volume;

			source.connect(gain);
			gain.connect(ctx.destination);

			source.onended = () => {
				setIsPlaying(false);
				onEnd?.();
			};

			source.start(0);
			sourceRef.current = source;
			gainRef.current = gain;
			setIsPlaying(true);
			onPlay?.();
		},
		[soundEnabled, playbackRate, volume, interrupt, stop, onPlay, onEnd],
	);

	const pause = useCallback(() => {
		stop();
		onPause?.();
	}, [stop, onPause]);

	useEffect(() => {
		if (gainRef.current) {
			gainRef.current.gain.value = volume;
		}
	}, [volume]);

	useEffect(() => {
		return () => {
			if (sourceRef.current) {
				try {
					sourceRef.current.stop();
				} catch {
					// Already stopped
				}
			}
		};
	}, []);

	return [play, { stop, pause, isPlaying, duration, sound }] as const;
}

import type { SoundAsset } from "@/lib/soundcn/sound-types";

export const metalClickSound: SoundAsset = {
	name: "metal-click",
	dataUri:
		"data:audio/mpeg;base64,",
	duration: 0.446,
	format: "mp3",
	license: "CC0",
	author: "Kenney",
};

let audioContext: AudioContext | null = null;
const bufferCache = new Map<string, AudioBuffer>();

export function getAudioContext(): AudioContext {
	if (!audioContext) {
		audioContext = new AudioContext();
	}
	return audioContext;
}

export async function decodeAudioData(dataUri: string): Promise<AudioBuffer> {
	const cached = bufferCache.get(dataUri);
	if (cached) return cached;

	const context = getAudioContext();
	const base64 = dataUri.split(",")[1];
	if (!base64) throw new Error("Invalid sound data URI");

	const binaryString = atob(base64);
	const bytes = new Uint8Array(binaryString.length);
	for (let index = 0; index < binaryString.length; index++) {
		bytes[index] = binaryString.charCodeAt(index);
	}

	const audioBuffer = await context.decodeAudioData(bytes.buffer.slice(0));
	bufferCache.set(dataUri, audioBuffer);
	return audioBuffer;
}

export interface SoundAsset {
	name: string;
	dataUri: string;
	duration: number;
	format: "mp3" | "wav" | "ogg";
	license: "CC0" | "OGA-BY" | "MIT";
	author: string;
}

export interface UseSoundOptions {
	volume?: number;
	playbackRate?: number;
	interrupt?: boolean;
	soundEnabled?: boolean;
	onPlay?: () => void;
	onEnd?: () => void;
	onPause?: () => void;
	onStop?: () => void;
}

export type PlayFunction = (overrides?: {
	volume?: number;
	playbackRate?: number;
}) => void;

export interface SoundControls {
	stop: () => void;
	pause: () => void;
	isPlaying: boolean;
	duration: number | null;
	sound: SoundAsset;
}

export type UseSoundReturn = readonly [PlayFunction, SoundControls];

"use client";

import {
	MotionConfig,
	motion,
	useMotionTemplate,
	useMotionValue,
	useReducedMotion,
	useSpring,
} from "motion/react";
import {
	type ComponentPropsWithoutRef,
	type FocusEvent,
	forwardRef,
	type PointerEvent as ReactPointerEvent,
	useCallback,
	useEffect,
	useRef,
	useState,
} from "react";

import { cn } from "@/lib/utils";

export interface PeepingButtonProps extends ComponentPropsWithoutRef<"button"> {
	/** Classes applied to the hinged, visible face of the button. */
	coverClassName?: string;
	/** Delay before each peek, or a random range in milliseconds. */
	peekDelay?: number | readonly [min: number, max: number];
	/** How long the eyes remain visible in milliseconds. */
	peekDuration?: number;
	/** Disable the automatic peeking behavior while keeping a usable button. */
	autoPeek?: boolean;
}

const DEFAULT_PEEK_DELAY = [2800, 5200] as const;
const DEFAULT_PEEK_DURATION = 2200;

function resolvePeekDelay(min: number, max: number) {
	return min + Math.random() * (max - min);
}

export const PeepingButton = forwardRef<HTMLButtonElement, PeepingButtonProps>(
	(
		{
			autoPeek = true,
			children,
			className,
			coverClassName,
			disabled,
			onBlur,
			onFocus,
			onPointerEnter,
			onPointerLeave,
			peekDelay = DEFAULT_PEEK_DELAY,
			peekDuration = DEFAULT_PEEK_DURATION,
			type = "button",
			...props
		},
		ref,
	) => {
		const eyesRef = useRef<HTMLSpanElement>(null);
		const [autoOpen, setAutoOpen] = useState(false);
		const [isEngaged, setIsEngaged] = useState(false);
		const [isPageVisible, setIsPageVisible] = useState(true);
		const reduceMotion = useReducedMotion();

		const pupilX = useMotionValue(0);
		const pupilY = useMotionValue(0);
		const smoothPupilX = useSpring(pupilX, {
			duration: 0.35,
			bounce: 0.16,
		});
		const smoothPupilY = useSpring(pupilY, {
			duration: 0.35,
			bounce: 0.16,
		});
		const pupilTransform = useMotionTemplate`translate3d(calc(-50% + ${smoothPupilX}px), calc(-50% + ${smoothPupilY}px), 0)`;
		const peekDelayStart =
			typeof peekDelay === "number" ? peekDelay : peekDelay[0];
		const peekDelayEnd =
			typeof peekDelay === "number" ? peekDelay : peekDelay[1];
		const peekDelayMin = Math.min(peekDelayStart, peekDelayEnd);
		const peekDelayMax = Math.max(peekDelayStart, peekDelayEnd);

		const canPeek =
			autoPeek && !disabled && isPageVisible && reduceMotion !== true;
		const isOpen = canPeek && autoOpen && !isEngaged;

		useEffect(() => {
			function handleVisibilityChange() {
				const visible = document.visibilityState === "visible";
				setIsPageVisible(visible);
				if (!visible) setAutoOpen(false);
			}

			handleVisibilityChange();
			document.addEventListener("visibilitychange", handleVisibilityChange);
			return () =>
				document.removeEventListener(
					"visibilitychange",
					handleVisibilityChange,
				);
		}, []);

		useEffect(() => {
			if (!canPeek || isEngaged) {
				setAutoOpen(false);
				return;
			}

			const timeout = window.setTimeout(
				() => setAutoOpen((open) => !open),
				autoOpen ? peekDuration : resolvePeekDelay(peekDelayMin, peekDelayMax),
			);

			return () => window.clearTimeout(timeout);
		}, [
			autoOpen,
			canPeek,
			isEngaged,
			peekDelayMax,
			peekDelayMin,
			peekDuration,
		]);

		const pointEyesAt = useCallback(
			(clientX: number, clientY: number) => {
				const eyes = eyesRef.current;
				if (!eyes) return;

				const bounds = eyes.getBoundingClientRect();
				const deltaX = clientX - (bounds.left + bounds.width / 2);
				const deltaY = clientY - (bounds.top + bounds.height / 2);
				const distance = Math.hypot(deltaX, deltaY);
				const strength = Math.min(distance / 240, 1);
				const angle = Math.atan2(deltaY, deltaX);

				pupilX.set(Math.cos(angle) * 2.25 * strength);
				pupilY.set(Math.sin(angle) * 1.75 * strength);
			},
			[pupilX, pupilY],
		);

		useEffect(() => {
			if (!isOpen) {
				pupilX.set(0);
				pupilY.set(0);
				return;
			}

			function handlePointerMove(event: PointerEvent) {
				if (event.pointerType === "touch") return;
				pointEyesAt(event.clientX, event.clientY);
			}

			window.addEventListener("pointermove", handlePointerMove, {
				passive: true,
			});
			return () => window.removeEventListener("pointermove", handlePointerMove);
		}, [isOpen, pointEyesAt, pupilX, pupilY]);

		function handlePointerEnter(event: ReactPointerEvent<HTMLButtonElement>) {
			onPointerEnter?.(event);
			if (!event.defaultPrevented && event.pointerType !== "touch") {
				setIsEngaged(true);
			}
		}

		function handlePointerLeave(event: ReactPointerEvent<HTMLButtonElement>) {
			onPointerLeave?.(event);
			if (!event.defaultPrevented) setIsEngaged(false);
		}

		function handleFocus(event: FocusEvent<HTMLButtonElement>) {
			onFocus?.(event);
			if (!event.defaultPrevented) setIsEngaged(true);
		}

		function handleBlur(event: FocusEvent<HTMLButtonElement>) {
			onBlur?.(event);
			if (!event.defaultPrevented) setIsEngaged(false);
		}

		return (
			<MotionConfig reducedMotion="user">
				<button
					ref={ref}
					type={type}
					data-slot="peeping-button"
					data-peeking={isOpen ? "true" : "false"}
					disabled={disabled}
					onBlur={handleBlur}
					onFocus={handleFocus}
					onPointerEnter={handlePointerEnter}
					onPointerLeave={handlePointerLeave}
					className={cn(
						"group/peeping-button relative inline-grid min-w-36 touch-manipulation select-none place-items-center rounded-lg bg-muted text-sm outline-none",
						"transition-transform duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] active:scale-[0.97] motion-reduce:transform-none motion-reduce:transition-none",
						"focus-visible:ring-3 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50",
						className,
					)}
					{...props}
				>
					<span
						ref={eyesRef}
						aria-hidden="true"
						className="pointer-events-none absolute right-[0.9em] bottom-[0.55em] flex items-center gap-[0.35em]"
					>
						{["left", "right"].map((eye) => (
							<motion.span
								key={eye}
								className="relative size-[0.72em] overflow-hidden rounded-full bg-foreground"
								animate={
									reduceMotion === true || !isOpen
										? { transform: "scaleY(1)" }
										: {
												transform: [
													"scaleY(1)",
													"scaleY(1)",
													"scaleY(0.12)",
													"scaleY(1)",
												],
											}
								}
								transition={{
									duration: 4,
									times: [0, 0.92, 0.96, 1],
									repeat: Number.POSITIVE_INFINITY,
									ease: "linear",
								}}
							>
								<motion.span
									className="absolute top-1/2 left-1/2 size-[0.34em] rounded-full bg-background"
									style={{ transform: pupilTransform }}
								/>
							</motion.span>
						))}
					</span>

					<motion.span
						className={cn(
							"pointer-events-none absolute inset-0 flex origin-[1.25em_50%] items-center justify-center rounded-[inherit] border border-border bg-card px-5 py-3 font-medium text-card-foreground shadow-xs",
							coverClassName,
						)}
						animate={{
							transform: isOpen ? "rotate(-11deg)" : "rotate(0deg)",
						}}
						transition={
							isOpen
								? { type: "spring", duration: 0.45, bounce: 0.18 }
								: {
										duration: 0.2,
										ease: [0.23, 1, 0.32, 1],
									}
						}
					>
						{children}
					</motion.span>

					<span
						aria-hidden="true"
						className="invisible block px-5 py-3 font-medium"
					>
						{children}
					</span>
				</button>
			</MotionConfig>
		);
	},
);

PeepingButton.displayName = "PeepingButton";

