					const isPinned = pinned.includes(email.id);
					const pin: SwipeAction = {
						id: "pin",
						label: isPinned ? "Unpin" : "Pin",
						icon: isPinned ? <PinOff /> : <Pin />,
						tone: "amber",
						announce: `${isPinned ? "Unpinned" : "Pinned"} ${email.sender}'s email`,
						onAction: () =>
							setPinned((current) =>
								isPinned
									? current.filter((id) => id !== email.id)
