							),
					};
					const archive: SwipeAction = {
						id: "archive",
						label: "Archive",
						icon: <Archive />,
						tone: "blue",
						destructive: true,
						announce: `Archived ${email.sender}'s email`,
						onAction: () => remove(email.id),
					};
					const del: SwipeAction = {
						id: "delete",
						label: "Delete",
						icon: <Trash2 />,
						tone: "destructive",
						destructive: true,
						announce: `Deleted ${email.sender}'s email`,
						onAction: () => remove(email.id),
