										<span className="shrink-0 text-muted-foreground text-xs tabular-nums">
											{email.time}
										</span>
									</div>
									<p className="truncate text-muted-foreground text-sm">
										{email.subject}
									</p>
								</div>
							</div>
						</SwipeActions>
					);
				})}
			</SwipeList>

			{emails.length === 0 ? (
				<p className="px-4 py-10 text-center text-muted-foreground text-sm">
					All caught up.
				</p>
			) : null}
		</div>
	);
}

